(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("arist-peace-e",[{"st": "—", "sp": "HDR", "t": "ΕΙΡΗΝΗ"}, {"st": null, "sp": "Οἰκέτης Α", "t": "αἶρ᾽ αἶρε μᾶζαν ὡς τάχιστα κανθάρῳ."}, {"st": null, "sp": "Οἰκέτης Β", "t": "ἰδού. δὸς αὐτῷ, τῷ κάκιστ᾽ ἀπολουμένῳ<br>καὶ μήποτ᾽ αὐτῆς μᾶζαν ἡδίω φάγοι."}, {"st": null, "sp": "Οἰκέτης Α", "t": "δὸς μᾶζαν ἑτέραν, ἐξ ὀνίδων πεπλασμένην."}, {"st": null, "sp": "Οἰκέτης Β", "t": "ἰδοὺ μάλ᾽ αὖφις. ποῦ γὰρ ἣν νῦν δὴ ᾽φερες;<br>κατέφαγεν;"}, {"st": null, "sp": "Οἰκέτης Α", "t": "οὐ μὰ τὸν Δἴ ἀλλ᾽ ἐξαρπάσας<br>ὅλην ἐνέκαψε περικυλίσας τοῖν ποδοῖν.<br>ἀλλ᾽ ὡς τάχιστα τρῖβε πολλὰς καὶ πυκνάς."}, {"st": "10", "sp": "Οἰκέτης Β", "t": "ἄνδρες κοπρολόγοι προσλάβεσθε πρὸς θεῶν,<br>εἰ μή με βούλεσθ᾽ ἀποπνιγέντα περιιδεῖν."}, {"st": null, "sp": "Οἰκέτης Α", "t": "ἑτέραν ἑτέραν δός, παιδὸς ἡταιρηκότος·<br>τετριμμένης γάρ φησιν ἐπιθυμεῖν."}, {"st": null, "sp": "Οἰκέτης Β", "t": "ἰδού.<br>ἑνὸς μὲν ὦνδρες ἀπολελύσθαι μοι δοκῶ·<br>οὐδεὶς γὰρ ἂν φαίη με μάττοντ᾽ ἐσθίειν."}, {"st": null, "sp": "Οἰκέτης Α", "t": "αἰβοῖ, φέρ᾽ ἄλλην χἀτέραν μοι χἀτέραν,<br>καὶ τρῖβ᾽ &lt;ἔθ᾽&gt; ἑτέρας."}, {"st": null, "sp": "Οἰκέτης Β", "t": "μὰ τὸν Ἀπόλλω ᾽γὼ μὲν οὔ·<br>οὐ γὰρ ἔθ᾽ οἶός τ᾽ εἴμ᾽ ὑπερέχειν τῆς ἀντλίας."}, {"st": null, "sp": "Οἰκέτης Α", "t": "αὐτὴν ἄρ᾽ οἴσω συλλαβὼν τὴν ἀντλίαν."}, {"st": null, "sp": "Οἰκέτης Β", "t": "νὴ τὸν Δί᾽ ἐς κόρακάς γε καὶ σαυτόν γε πρός.<br>ὑμῶν δέ γ᾽ εἴ τις οἶδ᾽ ἐμοὶ κατειπάτω,<br>πόθεν ἂν πριαίμην ῥῖνα μὴ τετρημένην.<br>οὐδὲν γὰρ ἔργον ἦν ἄρ᾽ ἀθλιώτερον<br>ἢ κανθάρῳ μάττοντα παρέχειν ἐσθίειν.<br>ὗς μὲν γάρ, ὥσπερ ἂν χέσῃ τις, ἢ κύων<br>φαύλως ἐρείδει· τοῦτο δ᾽ ὑπὸ φρονήματος<br>βρενθύεταί τε καὶ φαγεῖν οὐκ ἀξιοῖ,<br>ἢν μὴ παραθῶ τρίψας δι᾽ ἡμέρας ὅλης<br>ὥσπερ γυναικὶ γογγύλην μεμαγμένην.<br>ἀλλ᾽ εἰ πέπαυται τῆς ἐδωδῆς σκέψομαι<br>τῃδὶ παροίξας τῆς θύρας, ἵνα μή μ᾽ ἴδῃ.<br>ἔρειδε, μὴ παύσαιο μηδέποτ᾽ ἐσθίων<br>τέως ἕως σαυτὸν λάθοις διαρραγείς.<br>οἷον δὲ κύψας ὁ κατάρατος ἐσθίει,<br>ὥσπερ παλαιστής, παραβαλὼν τοὺς γομφίους,<br>καὶ ταῦτα τὴν κεφαλήν τε καὶ τὼ χεῖρέ πως<br>ὡδὶ περιάγων, ὥσπερ οἱ τὰ σχοινία<br>τὰ παχέα συμβάλλοντες ἐς τὰς ὁλκάδας.<br>μιαρὸν τὸ χρῆμα καὶ κάκοσμον καὶ βορόν·<br>χὤτου ποτ᾽ ἐστὶ δαιμόνων ἡ προσβολὴ<br>οὐκ οἶδ᾽. Ἀφροδίτης μὲν γὰρ οὔ μοι φαίνεται,<br>οὐ μὴν Χαρίτων γε."}, {"st": null, "sp": "Οἰκέτης Α", "t": "τοῦ γάρ ἐστ᾽;"}, {"st": null, "sp": "Οἰκέτης Β", "t": "οὐκ ἔσθ᾽ ὅπως<br>τοῦτ᾽ ἔστι τὸ τέρας οὐ Διὸς καταιβάτου."}, {"st": null, "sp": "Οἰκέτης Α", "t": "οὐκοῦν ἂν ἤδη τῶν θεατῶν τις λέγοι<br>νεανίας δοκησίσοφος, “τὸ δὲ πρᾶγμα τί;<br>ὁ κάνθαρος δὲ πρὸς τί;” κᾆτ᾽ αὐτῷ γ᾽ ἀνὴρ<br>Ἰωνικός τίς φησι παρακαθήμενος·<br>“δοκέω μέν, ἐς Κλέωνα τοῦτ᾽ αἰνίσσεται,<br>ὡς κεῖνος ἀναιδέως τὴν σπατίλην ἐσθίει”."}, {"st": null, "sp": "Οἰκέτης Β", "t": "ἀλλ᾽ εἰσιὼν τῷ κανθάρῳ δώσω πιεῖν."}, {"st": null, "sp": "Οἰκέτης Α", "t": "ἐγὼ δὲ τὸν λόγον γε τοῖσι παιδίοις<br>καὶ τοῖσιν ἀνδρίοισι καὶ τοῖς ἀνδράσιν<br>καὶ τοῖς ὑπερτάτοισιν ἀνδράσιν φράσω<br>καὶ τοῖς ὑπερηνορέουσιν ἔτι τούτοις μάλα.<br>ὁ δεσπότης μου μαίνεται καινὸν τρόπον,<br>οὐχ ὅνπερ ὑμεῖς, ἀλλ᾽ ἕτερον καινὸν πάνυ.<br>δι᾽ ἡμέρας γὰρ ἐς τὸν οὐρανὸν βλέπων<br>ὡδὶ κεχηνὼς λοιδορεῖται τῷ Διὶ<br>καί φησιν, “ὦ Ζεῦ τί ποτε βουλεύει ποιεῖν;<br>κατάθου τὸ κόρημα· μὴ ᾽κκόρει τὴν Ἑλλάδα”.<br>ἔα ἔα.<br>σιγήσαθ᾽, ὡς φωνῆς ἀκούειν μοι δοκῶ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ Ζεῦ τί δρασείεις ποθ᾽ ἡμῶν τὸν λεών;<br>λήσεις σεαυτὸν τὰς πόλεις ἐκκοκκίσας."}, {"st": null, "sp": "Οἰκέτης Α", "t": "τοῦτ᾽ ἔστι τουτὶ τὸ κακὸν αὔθ᾽ οὑγὼ ᾽λεγον.<br>τὸ γὰρ παράδειγμα τῶν μανιῶν ἀκούετε·<br>ἃ δ᾽ εἶπε πρῶτον ἡνίκ᾽ ἤρχεθ᾽ ἡ χολή,<br>πεύσεσθ᾽. ἔφασκε γὰρ πρὸς αὑτὸν ἐνθαδί·<br>“πῶς ἄν ποτ᾽ ἀφικοίμην ἂν εὐθὺ τοῦ Διός;”<br>ἔπειτα λεπτὰ κλιμάκια ποιούμενος,<br>πρὸς ταῦτ᾽ ἀνηρριχᾶτ᾽ ἂν ἐς τὸν οὐρανόν,<br>ἕως ξυνετρίβη τῆς κεφαλῆς καταρρυείς.<br>ἐχθὲς δὲ μετὰ ταῦτ᾽ ἐκφθαρεὶς οὐκ οἶδ᾽ ὅποι<br>εἰσήγαγ᾽ Αἰτναῖον μέγιστον κάνθαρον,<br>κἄπειτα τοῦτον ἱπποκομεῖν μ᾽ ἠνάγκασεν,<br>καὐτὸς καταψῶν αὐτὸν ὥσπερ πωλίον,<br>“ὦ Πηγάσειον”, φησί, “γενναῖον πτερόν,<br>ὅπως πετήσει μ᾽ εὐθὺ τοῦ Διὸς λαβών”.<br>ἀλλ᾽ ὅ τι ποιεῖ τῃδὶ διακύψας ὄψομαι.<br>οἴμοι τάλας· ἴτε δεῦρο δεῦρ ὦ γείτονες·<br>ὁ δεσπότης γάρ μου μετέωρος αἴρεται<br>ἱππηδὸν ἐς τὸν ἀέρ᾽ ἐπὶ τοῦ κανθάρου."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἥσυχος ἥσυχος, ἠρέμα, κάνθων·<br>μή μοι σοβαρῶς χώρει λίαν<br>εὐθὺς ἀπ᾽ ἀρχῆς ῥώμῃ πίσυνος,<br>πρὶν ἂν ἰδίῃς καὶ διαλύσῃς<br>ἄρθρων ἶνας πτερύγων ῥύμῃ.<br>καὶ μὴ πνεῖ μοι κακόν, ἀντιβολῶ σ᾽·<br>εἰ δὲ ποιήσεις τοῦτο, κατ᾽ οἴκους<br>αὐτοῦ μεῖνον τοὺς ἡμετέρους."}, {"st": "90", "sp": "Οἰκέτης Α", "t": "ὦ δέσποτ᾽ ἄναξ ὡς παραπαίεις."}, {"st": null, "sp": "Τρυγαῖος", "t": "σίγα σίγα."}, {"st": null, "sp": "Οἰκέτης Α", "t": "ποῖ δῆτ᾽ ἄλλως μετεωροκοπεῖς;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὑπὲρ Ἑλλήνων πάντων πέτομαι<br>τόλμημα νέον παλαμησάμενος."}, {"st": "95", "sp": "Οἰκέτης Α", "t": "τί πέτει; τί μάτην οὐχ ὑγιαίνεις;"}, {"st": null, "sp": "Τρυγαῖος", "t": "εὐφημεῖν χρὴ καὶ μὴ φλαῦρον<br>μηδὲν γρύζειν ἀλλ᾽ ὀλολύζειν·<br>τοῖς τ᾽ ἀνθρώποισι φράσον σιγᾶν,<br>τοὺς τε κοπρῶνας καὶ τὰς λαύρας<br>καιναῖς πλίνθοισιν ἀνοικοδομεῖν<br>καὶ τοὺς πρωκτοὺς ἐπικλῄειν."}, {"st": null, "sp": "Οἰκέτης Α", "t": "οὐκ ἔσθ᾽ ὅπως σιγήσομ᾽, ἢν μή μοι φράσῃς<br>ὅποι πέτεσθαι διανοεῖ."}, {"st": null, "sp": "Τρυγαῖος", "t": "τί δ᾽ ἄλλο γ᾽ ἢ<br>ὡς τὸν Δί᾽ ἐς τὸν οὐρανόν;"}, {"st": null, "sp": "Οἰκέτης Α", "t": "τίνα νοῦν ἔχων;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐρησόμενος ἐκεῖνον Ἑλλήνων πέρι<br>ἁπαξαπάντων ὅ τι ποιεῖν βουλεύεται."}, {"st": null, "sp": "Οἰκέτης Α", "t": "ἐὰν δὲ μή σοι καταγορεύῃ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "γράψομαι<br>Μήδοισιν αὐτὸν προδιδόναι τὴν Ἑλλάδα."}, {"st": null, "sp": "Οἰκέτης Α", "t": "μὰ τὸν Διόνυσον οὐδέποτε ζῶντός γ᾽ ἐμοῦ."}, {"st": "110", "sp": "Τρυγαῖος", "t": "οὐκ ἔστι παρὰ ταῦτ᾽ ἄλλ᾽."}, {"st": null, "sp": "Οἰκέτης Α", "t": "ἰοὺ ἰοὺ ἰού·<br>ὦ παιδί᾽ ὁ πατὴρ ἀπολιπὼν ἀπέρχεται<br>ὑμᾶς ἐρήμους ἐς τὸν οὐρανὸν λάθρᾳ.<br>ἀλλ᾽ ἀντιβολεῖτε τὸν πατέρ ὦ κακοδαίμονα."}, {"st": null, "sp": "Παιδίον", "t": "ὦ πάτερ ὦ πάτερ ἆρ᾽ ἔτυμός γε<br>δώμασιν ἡμετέροις φάτις ἥκει,<br>ὡς σὺ μετ᾽ ὀρνίθων προλιρὼν ἐμὲ<br>ἐς κόρακας βαδιεῖ μεταμώνιος;<br>ἔστι τι τῶνδ᾽ ἐτύμως; εἴπ᾽ ὦ πάτερ, εἴ τι φιλεῖς με."}, {"st": null, "sp": "Τρυγαῖος", "t": "δοξάσαι ἔστι κόραι, τὸ δ᾽ ἐτήτυμον ἄχθομαι ὑμῖν,<br>ἡνίκ᾽ ἂν αἰτίζητ᾽ ἄρτον πάππαν με καλοῦσαι,<br>ἔνδον δ᾽ ἀργυρίου μηδὲ ψακὰς ᾖ πάνυ πάμπαν.<br>ἢν δ᾽ ἐγὼ εὖ πράξας ἔλθω πάλιν, ἕξετ᾽ ἐν ὥρᾳ<br>κολλύραν μεγάλην καὶ κόνδυλον ὄψον ἐρ᾽ αὐτῇ."}, {"st": "125", "sp": "Παιδίον", "t": "καὶ τίς πόρος σοι τῆς ὁδοῦ γενήσεται;<br>ναῦς μὲν γὰρ οὐκ ἄξει σε ταύτην τὴν ὁδόν."}, {"st": null, "sp": "Τρυγαῖος", "t": "πτηνὸς πορεύσει πῶλος· οὐ ναυσθλώσομαι."}, {"st": null, "sp": "Παιδίον", "t": "τίς δ᾽ ἡ ᾽πίνοιά σοὐστὶν ὥστε κάνθαρον<br>ζεύξαντ᾽ ἐλαύνειν ἐς θεοὺς ὦ παππία;"}, {"st": "130", "sp": "Τρυγαῖος", "t": "ἐν τοῖσιν Αἰσώπου λόγοις ἐξηυρέθη<br>μόνος πετεινῶν ἐς θεοὺς ἀφιγμένος."}, {"st": null, "sp": "Παιδίον", "t": "ἄπιστον εἶπας μῦθον ὦ πάτερ πάτερ,<br>ὅπως κάκοσμον ζῷον ἦλθεν ἐς θεούς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἦλθεν κατ᾽ ἔχθραν αἰετοῦ πάλαι ποτέ,<br>ᾤ᾽ ἐκκυλίνδων κἀντιτιμωρούμενος."}, {"st": null, "sp": "Παιδίον", "t": "οὐκοῦν ἐχρῆν σε Πηγάσου ζεῦξαι πτερόν,<br>ὅπως ἐφαίνου τοῖς θεοῖς τραγικώτερος."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὦ μέλ᾽ ἄν μοι σιτίων διπλῶν ἔδει·<br>νῦν δ᾽ ἃττ᾽ ἂν αὐτὸς καταφάγω τὰ σιτία,<br>τούτοισι τοῖς αὐτοῖσι τοῦτον χορτάσω."}, {"st": null, "sp": "Παιδίον", "t": "τί δ᾽ ἢν ἐς ὑγρὸν πόντιον πέσῃ βάθος;<br>πῶς ἐξολισθεῖν πτηνὸς ὢν δυνήσεται;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐπίτηδες εἶχον πηδάλιον, ᾧ χρήσομαι·<br>τὸ δὲ πλοῖον ἔσται Ναξιουργὴς κάνθαρος."}, {"st": null, "sp": "Παιδίον", "t": "λιμὴν δὲ τίς σε δέξεται φορούμενον;"}, {"st": "145", "sp": "Τρυγαῖος", "t": "ἐν Πειραιεῖ δήπου ᾽στὶ Κανθάρου λιμήν."}, {"st": null, "sp": "Παιδίον", "t": "ἐκεῖνο τήρει, μὴ σφαλεὶς καταρρυῇς<br>ἐντεῦθεν, εἶτα χωλὸς ὢν Εὐριπίδῃ<br>λόγον παράσχῃς καὶ τραγῳδία γένῃ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐμοὶ μελήσει ταῦτά γ᾽. ἀλλὰ χαίρετε.<br>ὑμεῖς δέ γ᾽, ὑπὲρ ὧν τοὺς πόνους ἐγὼ πονῶ,<br>μὴ βδεῖτε μηδὲ χέζεθ᾽ ἡμερῶν τριῶν·<br>ὡς εἰ μετέωρος οὗτος ὢν ὀσφρήσεται,<br>κατωκάρα ῥίψας με βουκολήσεται.<br>ἀλλ᾽ ἄγε Πήγασε χώρει χαίρων,<br>χρυσοχάλινον πάταγον ψαλίων<br>διακινήσας φαιδροῖς ὠσίν.<br>τί ποιεῖς; τί ποιεῖς; ποῖ παρακλίνεις<br>τοὺς μυκτῆρας; πρὸς τὰς λαύρας.<br>ἵει σαυτὸν θαρρῶν ἀπὸ γῆς,<br>κᾆτα δρομαίαν πτέρυγ᾽ ἐκτείνων<br>ὀρθὸς χώρει Διὸς εἰς αὐλάς,<br>ἀπὸ μὲν κάκκης τὴν ῥῖν᾽ ἀπέχων,<br>ἀπὸ δ᾽ ἡμερίων σίτων πάντων.<br>ἄνθρωπε τί δρᾷς, οὗτος ὁ χέζων<br>ἐν Πειραιεῖ παρὰ ταῖς πόρναις;<br>ἀπολεῖς μ᾽ ἀπολεῖς. οὐ κατορύξεις<br>κἀπιφορήσεις τῆς γῆς πολλήν,<br>κἀπιφυτεύσεις ἕρπυλλον ἄνω<br>καὶ μύρον ἐπιχεῖς; ὡς ἤν τι πεσὼν<br>ἐνθένδε πάθω, τοὐμοῦ θανάτου<br>πέντε τάλανθ᾽ ἡ πόλις ἡ Χίων<br>διὰ τὸν σὸν πρωκτὸν ὀφλήσει.<br>οἴμ᾽ ὡς δέδοικα, κοὐκέτι σκώπτων λέγω.<br>ὦ μηχανοποιὲ πρόσεχε τὸν νοῦν ὡς ἐμέ·<br>ἤδη στρέφει τι πνεῦμα περὶ τὸν ὀμφαλόν,<br>κεἰ μὴ φυλάξει, χορτάσω τὸν κάνθαρον.<br>ἀτὰρ ἐγγὺς εἶναι τῶν θεῶν ἐμοὶ δοκῶ,<br>καὶ δὴ καθορῶ τὴν οἰκίαν τὴν τοῦ Διός.<br>τίς ἐν Διὸς θύραισιν; οὐκ ἀνοίξετε;"}, {"st": null, "sp": "Ἑρμῆς", "t": "πόθεν βροτοῦ με προσέβαλ᾽; ὦναξ Ἡράκλεις<br>τουτὶ τί ἐστι τὸ κακόν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἱπποκάνθαρος."}, {"st": "185", "sp": "Ἑρμῆς", "t": "ὦ βδελυρὲ καὶ τολμηρὲ κἀναίσχυντε σὺ<br>καὶ μιαρὲ καὶ παμμίαρε καὶ μιαρώτατε,<br>πῶς δεῦρ᾽ ἀνῆλθες ὦ μιαρῶν μιαρώτατε;<br>τί σοί ποτ᾽ ἔστ᾽ ὄνομ᾽; οὐκ ἐρεῖς;"}, {"st": null, "sp": "Τρυγαῖος", "t": "μιαρώτατος."}, {"st": null, "sp": "Ἑρμῆς", "t": "ποδαπὸς τὸ γένος δ᾽ εἶ; φράζε μοι."}, {"st": null, "sp": "Τρυγαῖος", "t": "μιαρώτατος."}, {"st": null, "sp": "Ἑρμῆς", "t": "πατὴρ δέ σοι τίς ἐστ᾽;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐμοί; μιαρώτατος."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὔτοι μὰ τὴν γῆν ἔσθ᾽ ὅπως οὐκ ἀποθανεῖ,<br>εἰ μὴ κατερεῖς μοι τοὔνομ᾽ ὅ τι ποτ᾽ ἔστι σοι."}, {"st": null, "sp": "Τρυγαῖος", "t": "Τρυγαῖος Ἀθμονεύς, ἀμπελουργὸς δεξιός,<br>οὐ συκοφάντης οὐδ᾽ ἐραστὴς πραγμάτων."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἥκεις δὲ κατὰ τί;"}, {"st": null, "sp": "Τρυγαῖος", "t": "τὰ κρέα ταυτί σοι φέρων."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ δειλακρίων πῶς ἦλθες;"}, {"st": "195", "sp": "Τρυγαῖος", "t": "ὦ γλίσχρων ὁρᾷς<br>ὡς οὐκέτ᾽ εἶναί σοι δοκῶ μιαρώτατος;<br>ἴθι νυν κάλεσόν μοι τὸν Δί᾽."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἰὴ ἰὴ ἰή,<br>ὅτι οὐδὲ μέλλεις ἐγγὺς εἶναι τῶν θεῶν·<br>φροῦδοι γὰρ ἐχθές εἰσιν ἐξῳκισμένοι."}, {"st": null, "sp": "Τρυγαῖος", "t": "ποῖ γῆς;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἰδοὺ γῆς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλὰ ποῖ;"}, {"st": null, "sp": "Ἑρμῆς", "t": "πόρρω πάνυ;<br>ὑπ᾽ αὐτὸν ἀτεχνῶς τοὐρανοῦ τὸν κύτταρον."}, {"st": "200", "sp": "Τρυγαῖος", "t": "πῶς οὖν σὺ δῆτ᾽ ἐνταῦθα κατελείφθης μόνος;"}, {"st": null, "sp": "Ἑρμῆς", "t": "τὰ λοιπὰ τηρῶ σκευάρια τὰ τῶν θεῶν,<br>χυτρίδια καὶ σανίδια κἀμφορείδια."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐξῳκίσαντο δ᾽ οἱ θεοὶ τίνος οὕνεκα;"}, {"st": null, "sp": "Ἑρμῆς", "t": "Ἕλλησιν ὀργισθέντες. εἶτ᾽ ἐνταῦθα μὲν<br>ἵν᾽ ἦσαν αὐτοὶ τὸν Πόλεμον κατῴκισαν,<br>ὑμᾶς παραδόντες δρᾶν ἀτεχνῶς ὅ τι βούλεται·<br>αὐτοὶ δ᾽ ἀνῳκίσανθ᾽ ὅπως ἀνωτάτω,<br>ἵνα μὴ βλέποιεν μαχομένους ὑμᾶς ἔτι<br>μηδ᾽ ἀντιβολούντων μηδὲν αἰσθανοίατο."}, {"st": "210", "sp": "Τρυγαῖος", "t": "τοῦ δ᾽ οὕνεχ᾽ ἡμᾶς ταῦτ᾽ ἔδρασαν; εἰπέ μοι."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὁτιὴ πολεμεῖν ᾑρεῖσθ᾽ ἐκείνων πολλάκις<br>σπονδὰς ποιούντων· κεἰ μὲν οἱ Λακωνικοὶ<br>ὑπερβάλοιντο μικρόν, ἔλεγον ἂν ταδί·<br>“ναὶ τὼ σιὼ νῦν ὡττικίων δωσεῖ δίκαν”.<br>εἰ δ᾽ αὖ τι πράξαιτ᾽ ἀγαθὸν ἁττικωνικοί<br>κἄλθοιεν οἱ Λάκωνες εἰρήνης πέρι,<br>ἐλέγετ᾽ ἂν ὑμεῖς εὐθύς· “ἐξαπατώμεθα<br>νὴ τὴν Ἀθηνᾶν, νὴ Δί᾽, οὐχὶ πειστέον·<br>ἥξουσι καὖθις, ἢν ἔχωμεν τὴν Πύλον”."}, {"st": "220", "sp": "Τρυγαῖος", "t": "ὁ γοῦν χαρακτὴρ ἡμεδαπὸς τῶν ῥημάτων."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὧν οὕνεκ᾽ οὐκ οἶδ᾽ εἴ ποτ᾽ Εἰρήνην ἔτι<br>τὸ λοιπὸν ὄψεσθ᾽."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλὰ ποῖ γὰρ οἴχεται;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ὁ Πόλεμος αὐτὴν ἐνέβαλ᾽ εἰς ἄντρον βαθύ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐς ποῖον;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἐς τουτὶ τὸ κάτω, κἄπειθ᾽ ὁρᾷς<br>ὅσους ἄνωθεν ἐπεφόρησε τῶν λίθων,<br>ἵνα μὴ λάβητε μηδέποτ᾽ αὐτήν."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἰπέ μοι,<br>ἡμᾶς δὲ δὴ τί δρᾶν παρασκευάζεται;"}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐκ οἶδα πλὴν ἕν, ὅτι θυείαν ἑσπέρας<br>ὑπερφυᾶ τὸ μέγεθος εἰσηνέγκατο."}, {"st": "230", "sp": "Τρυγαῖος", "t": "τί δῆτα ταύτῃ τῇ θυείᾳ χρήσεται;"}, {"st": null, "sp": "Ἑρμῆς", "t": "τρίβειν ἐν αὐτῇ τὰς πόλεις βουλεύεται.<br>ἀλλ᾽ εἶμι· καὶ γὰρ ἐξιέναι γνώμην ἐμὴν<br>μέλλει· θορυβεῖ γοῦν ἔνδον."}, {"st": "235", "sp": "Τρυγαῖος", "t": "οἴμοι δείλαιος.<br>φέρ᾽ αὐτὸν ἀποδρῶ· καὶ γὰρ ὥσπερ ᾐσθόμην<br>καὐτὸς θυείας φθέγμα πολεμιστηρίας."}, {"st": null, "sp": "Πόλεμος", "t": "ἰὼ βροτοὶ βροτοὶ βροτοὶ πολυτλήμονες,<br>ὡς αὐτίκα μάλα τὰς γνάθους ἀλγήσετε."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦναξ Ἄπολλον τῆς θυείας τοῦ πλάτους,<br>ὅσον κακόν, καὶ τοῦ Πολέμου τοῦ βλέμματος.<br>ἆρ᾽ οὗτός ἐστ᾽ ἐκεῖνος ὃν καὶ φεύγομεν,<br>ὁ δεινός, ὁ ταλαύρινος, ὁ κατὰ τοῖν σκελοῖν;"}, {"st": null, "sp": "Πόλεμος", "t": "ἰὼ Πρασιαὶ τρὶς ἄθλιαι καὶ πεντάκις<br>καὶ πολλοδεκάκις, ὡς ἀπολεῖσθε τήμερον."}, {"st": "245", "sp": "Τρυγαῖος", "t": "τουτὶ μὲν ἄνδρες οὐδὲν ἡμῖν πρᾶγμά πω·<br>τὸ γὰρ κακὸν τοῦτ᾽ ἐστὶ τῆς Λακωνικῆς."}, {"st": null, "sp": "Πόλεμος", "t": "ὦ Μέγαρα Μέγαρ᾽ ὡς ἐπιτετρίψεσθ᾽ αὐτίκα<br>ἁπαξάπαντα καταμεμυττωτευμένα."}, {"st": null, "sp": "Τρυγαῖος", "t": "βαβαὶ βαβαιὰξ ὡς μεγάλα καὶ δριμέα<br>τοῖσι Μεγαρεῦσιν ἐνέβαλεν τὰ κλαύματα."}, {"st": "250", "sp": "Πόλεμος", "t": "ἰὼ Σικελία καὶ σὺ δ᾽ ὡς ἀπόλλυσαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "οἵα πόλις τάλαινα διακναισθήσεται."}, {"st": null, "sp": "Πόλεμος", "t": "φέρ᾽ ἐπιχέω καὶ τὸ μέλι τουτὶ τἀττικόν."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὗτος παραινῶ σοι μέλιτι χρῆσθἀτέρῳ.<br>τετρώβολον τοῦτ᾽ ἐστί· φείδου τἀττικοῦ."}, {"st": "255", "sp": "Πόλεμος", "t": "παῖ παῖ Κυδοιμέ."}, {"st": null, "sp": "Κύδοιμος", "t": "τί με καλεῖς;"}, {"st": null, "sp": "Πόλεμος", "t": "κλαύσει μακρά.<br>ἕστηκας ἀργός; οὑτοσί σοι κόνδυλος."}, {"st": null, "sp": "Κύδοιμος", "t": "ὡς δριμύς. οἴμοι μοι τάλας ὦ δέσποτα.<br>μῶν τῶν σκορόδων ἐνέβαλες ἐς τὸν κόνδυλον;"}, {"st": null, "sp": "Πόλεμος", "t": "οἴσεις ἀλετρίβανον τρέχων;"}, {"st": "260", "sp": "Κύδοιμος", "t": "ἀλλ᾽ ὦ μέλε<br>οὐκ ἔστιν ἡμῖν· ἐχθὲς εἰσῳκίσμεθα."}, {"st": null, "sp": "Πόλεμος", "t": "οὔκουν παρ᾽ Ἀθηναίων μεταθρέξει ταχὺ &lt;πάνυ&gt;;"}, {"st": null, "sp": "Κύδοιμος", "t": "ἔγωγε νὴ Δί᾽· εἰ δὲ μή γε, κλαύσομαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἄγε δὴ τί δρῶμεν ὦ πόνηρ᾽ ἀνθρώπια;<br>ὁρᾶτε τὸν κίνδυνον ἡμῖν ὡς μέγας·<br>εἴπερ γὰρ ἥξει τὸν ἀλετρίβανον φέρων,<br>τούτῳ ταράξει τὰς πόλεις καθήμενος.<br>ἀλλ᾽ ὦ Διόνυσ᾽ ἀπόλοιτο καὶ μὴ ᾽λθοι φέρων."}, {"st": null, "sp": "Πόλεμος", "t": "οὗτος."}, {"st": null, "sp": "Κύδοιμος", "t": "τί ἔστιν;"}, {"st": null, "sp": "Πόλεμος", "t": "οὐ φέρεις;"}, {"st": "270", "sp": "Κύδοιμος", "t": "τὸ δεῖνα γὰρ<br>ἀπόλωλ᾽ Ἀθηναίοισιν ἁλετρίβανος,<br>ὁ βυρσοπώλης, ὃς ἐκύκα τὴν Ἑλλάδα."}, {"st": null, "sp": "Τρυγαῖος", "t": "εὖ γ᾽ ὦ πότνια δέσποιν᾽ Ἀθηναία ποιῶν<br>ἀπόλωλ᾽ ἐκεῖνος κἀν δέοντι τῇ πόλει,<br>ἢ πρίν γε τὸν μυττωτὸν ἡμῖν ἐγχέαι."}, {"st": "275", "sp": "Πόλεμος", "t": "οὔκουν ἕτερον δῆτ᾽ ἐκ Λακεδαίμονος μέτει<br>ἀνύσας τι;"}, {"st": null, "sp": "Κύδοιμος", "t": "ταῦτ᾽ ὦ δέσποθ᾽."}, {"st": null, "sp": "Πόλεμος", "t": "ἧκέ νυν ταχύ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦνδρες τί πεισόμεσθα; νῦν ἀγὼν μέγας.<br>ἀλλ᾽ εἴ τις ὑμῶν ἐν Σαμοθρᾴκῃ τυγχάνει<br>μεμυημένος, νῦν ἐστιν εὔξασθαι καλὸν<br>ἀποστραφῆναι τοῦ μετιόντος τὼ πόδε."}, {"st": "280", "sp": "Κύδοιμος", "t": "οἴμοι τάλας, οἴμοι γε κἄτ᾽ οἴμοι μάλα."}, {"st": null, "sp": "Πόλεμος", "t": "τί ἔστι; μῶν οὐκ αὖ φέρεις;"}, {"st": null, "sp": "Κύδοιμος", "t": "ἀπόλωλε γὰρ<br>καὶ τοῖς Λακεδαιμονίοισιν ἁλετρίβανος."}, {"st": null, "sp": "Πόλεμος", "t": "πῶς ὦ πανοῦργ᾽;"}, {"st": null, "sp": "Κύδοιμος", "t": "ἐς τἀπὶ Θρᾴκης χωρία<br>χρήσαντες ἑτέροις αὐτὸν εἶτ᾽ ἀπώλεσαν."}, {"st": null, "sp": "Τρυγαῖος", "t": "εὖ γ᾽ εὖ γε ποιήσαντες ὦ Διοσκόρω.<br>ἴσως ἂν εὖ γένοιτο· θαρρεῖτ᾽ ὦ βροτοί."}, {"st": null, "sp": "Πόλεμος", "t": "ἀπόφερε τὰ σκεύη λαβὼν ταυτὶ πάλιν·<br>ἐγὼ δὲ δοίδυκ᾽ εἰσιὼν ποιήσομαι."}, {"st": "300", "sp": "Τρυγαῖος", "t": "νῦν τοῦτ᾽ ἐκεῖν᾽ ἥκει τὸ Δάτιδος μέλος,<br>ὃ δεφόμενός ποτ᾽ ᾖδε τῆς μεσημβρίας,<br>“ὡς ἥδομαι καὶ χαίρομαι κεὐφραίνομαι”.<br>νῦν ἐστιν ἡμῖν ὦνδρες Ἕλληνες καλὸν<br>ἀπαλλαγεῖσι πραγμάτων τε καὶ μαχῶν<br>ἐξελκύσαι τὴν πᾶσιν Εἰρήνην φίλην,<br>πρὶν ἕτερον αὖ δοίδυκα κωλῦσαί τινα.<br>ἀλλ᾽ ὦ γεωργοὶ κἄμποροι καὶ τέκτονες<br>καὶ δημιουργοὶ καὶ μέτοικοι καὶ ξένοι<br>καὶ νησιῶται, δεῦρ᾽ ἴτ᾽ ὦ πάντες λεῴ,<br>ὡς τάχιστ᾽ ἄμας λαβόντες καὶ μοχλοὺς καὶ σχοινία·<br>νῦν γὰρ ἡμῖν ἁρπάσαι πάρεστιν ἀγαθοῦ δαίμονος."}, {"st": null, "sp": "Χορός", "t": "δεῦρο πᾶς χώρει προθύμως εὐθὺ τῆς σωτηρίας.<br>ὦ Πανέλληνες βοηθήσωμεν, εἴπερ πώποτε,<br>τάξεων ἀπαλλαγέντες καὶ κακῶν φοινικικῶν·<br>ἡμέρα γὰρ ἐξέλαμψεν ἥδε μισολάμαχος.<br>πρὸς τάδ᾽ ἡμῖν, εἴ τι χρὴ δρᾶν, φράζε κἀρχιτεκτόνει·<br>οὐ γὰρ ἔσθ᾽ ὅπως ἀπειπεῖν ἂν δοκῶ μοι τήμερον,<br>πρὶν μοχλοῖς καὶ μηχαναῖσιν ἐς τὸ φῶς ἀνελκύσαι<br>τὴν θεῶν πασῶν μεγίστην καὶ φιλαμπελωτάτην."}, {"st": "310", "sp": "Τρυγαῖος", "t": "οὐ σιωπήσεσθ᾽, ὅπως μὴ περιχαρεῖς τῷ πράγματι<br>τὸν Πόλεμον ἐκζωπυρήσετ᾽ ἔνδοθεν κεκραγότες;"}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ ἀκούσαντες τοιούτου χαίρομεν κηρύγματος.<br>οὐ γὰρ ἦν ἔχοντας ἥκειν σιτί᾽ ἡμερῶν τριῶν."}, {"st": "315", "sp": "Τρυγαῖος", "t": "εὐλαβεῖσθέ νυν ἐκεῖνον τὸν κάτωθεν Κέρβερον,<br>μὴ παφλάζων καὶ κεκραγὼς ὥσπερ ἡνίκ᾽ ἐνθάδ᾽ ἦν,<br>ἐμποδὼν ἡμῖν γένηται τὴν θεὸν μὴ ᾽ξελκύσαι."}, {"st": null, "sp": "Χορός", "t": "οὔτι καὶ νῦν ἔστιν αὐτὴν ὅστις ἐξαιρήσεται,<br>ἢν ἅπαξ ἐς χεῖρας ἔλθῃ τὰς ἐμάς. ἰοῦ ἰοῦ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐξολεῖτέ μ᾽ ὦνδρες, εἰ μὴ τῆς βοῆς ἀνήσετε·<br>ἐκδραμὼν γὰρ πάντα ταυτὶ συνταράξει τοῖν ποδοῖν."}, {"st": null, "sp": "Χορός", "t": "ὡς κυκάτω καὶ πατείτω πάντα καὶ ταραττέτω,<br>οὐ γὰρ ἂν χαίροντες ἡμεῖς τήμερον παυσαίμεθ᾽ ἄν."}, {"st": null, "sp": "Τρυγαῖος", "t": "τί τὸ κακόν; τί πάσχετ᾽ ὦνδρες; μηδαμῶς πρὸς τῶν θεῶν<br>πρᾶγμα κάλλιστον διαφθείρητε διὰ τὰ σχήματα."}, {"st": "325", "sp": "Χορός", "t": "ἀλλ᾽ ἔγωγ᾽ οὐ σχηματίζειν βούλομ᾽, ἀλλ᾽ ὑφ᾽ ἡδονῆς<br>οὐκ ἐμοῦ κινοῦντος αὐτὼ τὼ σκέλει χορεύετον."}, {"st": null, "sp": "Τρυγαῖος", "t": "μή τι καὶ νυνί γ᾽ ἔτ᾽, ἀλλὰ παῦε παῦ᾽ ὀρχούμενος."}, {"st": null, "sp": "Χορός", "t": "ἢν ἰδοὺ καὶ δὴ πέπαυμαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "φῄς γε, παύει δ᾽ οὐδέπω."}, {"st": null, "sp": "Χορός", "t": "ἓν μὲν οὖν τουτί μ᾽ ἔασον ἑλκύσαι, καὶ μηκέτι."}, {"st": null, "sp": "Τρυγαῖος", "t": "τοῦτό νυν, καὶ μηκέτ᾽ ἄλλο μηδὲν ὀρχήσησθ᾽ ἔτι."}, {"st": "330", "sp": "Χορός", "t": "οὐκ ἂν ὀρχησαίμεθ᾽, εἴπερ ὠφελήσαιμέν τί σε."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὁρᾶτ᾽ οὔπω πέπαυσθε."}, {"st": null, "sp": "Χορός", "t": "τουτογὶ νὴ τὸν Δία<br>τὸ σκέλος ῥίψαντες ἤδη λήγομεν τὸ δεξιόν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐπιδίδωμι τοῦτό γ᾽ ὑμῖν ὥστε μὴ λυπεῖν ἔτι."}, {"st": null, "sp": "Χορός", "t": "ἀλλὰ καὶ τἀριστερόν τοί μ᾽ ἐστ᾽ ἀναγκαίως ἔχον.<br>ἥδομαι γὰρ καὶ γέγηθα καὶ πέπορδα καὶ γελῶ<br>μᾶλλον ἢ τὸ γῆρας ἐκδὺς ἐκφυγὼν τὴν ἀσπίδα."}, {"st": "345", "sp": "Τρυγαῖος", "t": "μή τι καὶ νυνί γε χαίρετ᾽· οὐ γὰρ ἴστε πω σαφῶς·<br>ἀλλ᾽ ὅταν λάβωμεν αὐτήν, τηνικαῦτα χαίρετε<br>καὶ βοᾶτε καὶ γελᾶτ᾽· ἤδη<br>γὰρ ἐξέσται τόθ᾽ ὑμῖν<br>πλεῖν μένειν βινεῖν καθεύδειν,<br>ἐς πανηγύρεις θεωρεῖν,<br>ἑστιᾶσθαι κοτταβίζειν,<br>“συβαρίζειν”<br>ἰοῦ ἰοῦ κεκραγέναι."}, {"st": "360", "sp": "Χορός", "t": "εἰ γὰρ ἐκγένοιτ᾽ ἰδεῖν ταύτην με τὴν ἡμέραν [ποτέ].<br>πολλὰ γὰρ ἀνεσχόμην πράγματά τε καὶ στιβάδας, ἃς<br>ἔλαχε Φορμίων·<br>κοὐκέτ᾽ ἄν μ᾽ εὕροις δικαστὴν δριμὺν οὐδὲ δύσκολον,<br>οὐδὲ τοὺς τρόπους γε δήπου σκληρὸν ὥσπερ καὶ πρὸ τοῦ,<br>ἀλλ᾽ ἁπαλὸν ἄν μ᾽ ἴδοις καὶ πολὺ νεώτερον,<br>ἀπαλλαγέντα πραγμάτων.<br>καὶ γὰρ ἱκανὸν χρόνον ἀπολλύμεθα καὶ κατατετρίμμεθα πλανώμενοι<br>ἐς Λύκειον κἀκ Λυκείου ξὺν δορὶ ξὺν ἀσπίδι.<br>ἀλλ᾽ ὅ τι μάλιστα χαριούμεθα ποιοῦντες, ἄγε<br>φράζε· σὲ γὰρ αὐτοκράτορ᾽ εἵλετ᾽ ἀγαθή τις ἡμῖν τύχη."}, {"st": null, "sp": "Τρυγαῖος", "t": "φέρε δὴ κατίδω ποῖ τοὺς λίθους ἀφέλξομεν."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ μιαρὲ καὶ τολμηρὲ τί ποιεῖν διανοεῖ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐδὲν πονηρόν, ἀλλ᾽ ὅπερ καὶ Κιλλικῶν."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀπόλωλας ὦ κακόδαιμον."}, {"st": "365", "sp": "Τρυγαῖος", "t": "οὐκοῦν ἢν λάχω.<br>Ἑρμῆς γὰρ ὢν κλήρῳ ποιήσεις οἶδ᾽ ὅτι."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀπόλωλας, ἐξόλωλας."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐς τίν᾽ ἡμέραν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "εἰς αὐτίκα μάλ᾽."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οὐδὲν ἠμπόληκά πω,<br>οὔτ᾽ ἄλφιτ᾽ οὔτε τυρόν, ὡς ἀπολούμενος."}, {"st": null, "sp": "Ἑρμῆς", "t": "καὶ μὴν ἐπιτέτριψαί γε."}, {"st": "370", "sp": "Τρυγαῖος", "t": "κᾆτα τῷ τρόπῳ<br>οὐκ ᾐσθόμην ἀγαθὸν τοσουτονὶ λαβών;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἆρ᾽ οἶσθα θάνατον ὅτι προεῖφ᾽ ὁ Ζεὺς ὃς ἂν<br>ταύτην ἀνορύττων εὑρεθῇ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "νῦν ἆρά με<br>ἅπασ᾽ ἀνάγκη ᾽στ᾽ ἀποθανεῖν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "εὖ ἴσθ᾽ ὅτι."}, {"st": "375", "sp": "Τρυγαῖος", "t": "ἐς χοιρίδιόν μοί νυν δάνεισον τρεῖς δραχμάς·<br>δεῖ γὰρ μυηθῆναί με πρὶν τεθνηκέναι."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ Ζεῦ κεραυνοβρόντα."}, {"st": null, "sp": "Τρυγαῖος", "t": "μὴ πρὸς τῶν θεῶν<br>ἡμῶν κατείπῃς, ἀντιβολῶ σε δέσποτα."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐκ ἂν σιωπήσαιμι."}, {"st": null, "sp": "Τρυγαῖος", "t": "ναὶ πρὸς τῶν κρεῶν,<br>ἁγὼ προθύμως σοι φέρων ἀφικόμην."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀλλ᾽ ὦ μέλ᾽ ὑπὸ τοῦ Διὸς ἀμαλδυνθήσομαι,<br>εἰ μὴ τετορήσω ταῦτα καὶ λακήσομαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "μή νυν λακήσῃς, λίσσομαί σ᾽ ὦρμῄδιον.<br>εἰπέ μοι, τί πάσχετ᾽ ὦνδρες; ἕστατ᾽ ἐκπεπληγμένοι.<br>ὦ πόνηροι μὴ σιωπᾶτ᾽· εἰ δὲ μή, λακήσεται."}, {"st": null, "sp": "Χορός", "t": "μηδαμῶς ὦ δέσποθ᾽ Ἑρμῆ, μηδαμῶς, μηδαμῶς,<br>εἴ τι κεχαρισμένον χοιρίδιον οἶσθα παρ᾽ ἐμοῦ γε κατεδηδοκώς,<br>τοῦτο μὴ φαῦλον νόμιζ᾽ ἐν τῷδε τῷ &lt;νῦν&gt; πράγματι."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐκ ἀκούεις οἷα θωπεύουσί σ᾽ ὦναξ δέσποτα;"}, {"st": null, "sp": "Χορός", "t": "“μὴ γένῃ παλίγκοτος ἀντιβολοῦσιν ἡμῖν”,<br>ὥστε τήνδε μὴ λαβεῖν·<br>ἀλλὰ χάρισ᾽ ὦ φιλανθρωπότατε καὶ μεγαλοδωρότατε δαιμόνων,<br>εἴ τι Πεισάνδρου βδελύττει τοὺς λόφους καὶ τὰς ὀφρῦς.<br>καί σε θυσίαισιν ἱεραῖσι προσόδοις τε μεγάλαισι<br>διὰ παντὸς ὦ δέσποτ᾽ ἀγαλοῦμεν ἡμεῖς ἀεί."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἴθ᾽, ἀντιβολῶ σ᾽, ἐλέησον αὐτῶν τὴν ὄπα,<br>ἐπεί σε καὶ τιμῶσι μᾶλλον ἢ πρὸ τοῦ.<br>κλέπται γάρ εἰσι νῦν γε μᾶλλον ἢ πρὸ τοῦ.<br>καί σοι φράσω τι πρᾶγμα δεινὸν καὶ μέγα,<br>ὃ τοῖς θεοῖς ἅπασιν ἐπιβουλεύεται."}, {"st": "405", "sp": "Ἑρμῆς", "t": "ἴθι δὴ κάτειπ᾽· ἴσως γὰρ ἂν πείσαις ἐμέ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἡ γὰρ Σελήνη χὠ πανοῦργος Ἥλιος<br>ὑμῖν ἐπιβουλεύοντε πολὺν ἤδη χρόνον<br>τοῖς βαρβάροισι προδίδοτον τὴν Ἑλλάδα."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἵνα δὴ τί τοῦτο δρᾶτον;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὁτιὴ νὴ Δία<br>ἡμεῖς μὲν ὑμῖν θύομεν, τούτοισι δὲ<br>οἱ βάρβαροι θύουσι. διὰ τοῦτ᾽ εἰκότως<br>βούλοιντ᾽ ἂν ἡμᾶς πάντας ἐξολωλέναι,<br>ἵνα τὰς τελετὰς λάβοιεν αὐτοὶ τῶν θεῶν."}, {"st": "415", "sp": "Ἑρμῆς", "t": "ταῦτ᾽ ἄρα πάλαι τῶν ἡμερῶν παρεκλεπτέτην<br>καὶ τοῦ κύκλου παρέτρωγον ὑφ᾽ ἁμαρτωλίας."}, {"st": null, "sp": "Τρυγαῖος", "t": "ναὶ μὰ Δία. πρὸς ταῦτ᾽ ὦ φίλ᾽ Ἑρμῆ ξύλλαβε<br>ἡμῖν προθύμως τήνδε καὶ ξυνέλκυσον.<br>καί σοι τὰ μεγάλ᾽ ἡμεῖς Παναθήναι᾽ ἄξομεν<br>πάσας τε τὰς ἄλλας τελετὰς τὰς τῶν θεῶν,<br>μυστήρι᾽ Ἑρμῇ, Διιπόλει᾽, Ἀδώνια·<br>ἄλλαι τέ σοι πόλεις πεπαυμέναι κακῶν<br>ἀλεξικάκῳ θύσουσιν Ἑρμῇ πανταχοῦ.<br>χἄτερ᾽ ἔτι πόλλ᾽ ἕξεις ἀγαθά. πρῶτον δέ σοι<br>δῶρον δίδωμι τήνδ᾽, ἵνα σπένδειν ἔχῃς."}, {"st": "425", "sp": "Ἑρμῆς", "t": "οἴμ᾽ ὡς ἐλεήμων εἴμ᾽ ἀεὶ τῶν χρυσίδων."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὑμέτερον ἐντεῦθεν ἔργον ὦνδρες. ἀλλὰ ταῖς ἄμαις<br>εἰσιόντες ὡς τάχιστα τοὺς λίθους ἀφέλκετε."}, {"st": "430", "sp": "Χορός", "t": "ταῦτα δράσομεν· σὺ δ᾽ ἡμῖν ὦ θεῶν σοφώτατε<br>ἅττα χρὴ ποιεῖν ἐφεστὼς φράζε δημιουργικῶς·<br>τἄλλα δ᾽ εὑρήσεις ὑπουργεῖν ὄντας ἡμᾶς οὐ κακούς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἄγε δὴ σὺ ταχέως ὕπεχε τὴν φιάλην, ὅπως<br>ἔργῳ ᾽φιαλοῦμεν εὐξάμενοι τοῖσιν θεοῖς."}, {"st": null, "sp": "Ἑρμῆς", "t": "σπονδὴ σπονδή·<br>εὐφημεῖτε εὐφημεῖτε."}, {"st": null, "sp": "Τρυγαῖος", "t": "σπένδοντες εὐχόμεσθα τὴν νῦν ἡμέραν<br>Ἕλλησιν ἄρξαι πᾶσι πολλῶν κἀγαθῶν,<br>χὤστις προθύμως ξυλλάβοι τῶν σχοινίων,<br>τοῦτον τὸν ἄνδρα μὴ λαβεῖν ποτ᾽ ἀσπίδα."}, {"st": "440", "sp": "Χορός", "t": "μὰ Δί᾽ ἀλλ᾽ ἐν εἰρήνῃ διαγαγεῖν τὸν βίον,<br>ἔχονθ᾽ ἑταίραν καὶ σκαλεύοντ᾽ ἄνθρακας."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅστις δὲ πόλεμον μᾶλλον εἶναι βούλεται"}, {"st": null, "sp": "Χορός", "t": "μηδέποτε παύσασθ᾽ αὐτὸν ὦ Διόνυσ᾽ ἄναξ<br>ἐκ τῶν ὀλεκράνων ἀκίδας ἐξαιρούμενον."}, {"st": "445", "sp": "Τρυγαῖος", "t": "κεἴ τις ἐπιθυμῶν ταξιαρχεῖν σοὶ φθονεῖ<br>ἐς φῶς ἀνελθεῖν ὦ πότνι᾽, ἐν ταῖσιν μάχαις"}, {"st": null, "sp": "Χορός", "t": "πάσχοι γε τοιαῦθ᾽ οἷάπερ Κλεώνυμος."}, {"st": null, "sp": "Τρυγαῖος", "t": "κεἴ τις δορυξὸς ἢ κάπηλος ἀσπίδων,<br>ἵν᾽ ἐμπολᾷ βέλτιον, ἐπιθυμεῖ μαχῶν"}, {"st": null, "sp": "Χορός", "t": "ληφθεὶς ὑπὸ λῃστῶν ἐσθίοι κριθὰς μόνας."}, {"st": null, "sp": "Τρυγαῖος", "t": "κεἴ τις στρατηγεῖν βουλόμενος μὴ ξυλλάβοι,<br>ἢ δοῦλος αὐτομολεῖν παρεσκευασμένος"}, {"st": null, "sp": "Χορός", "t": "ἐπὶ τοῦ τροχοῦ γ᾽ ἕλκοιτο μαστιγούμενος."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἡμῖν δ᾽ ἀγαθὰ γένοιτ᾽. ἰὴ παιὼν ἰή."}, {"st": null, "sp": "Χορός", "t": "ἄφελε τὸ παίειν ἀλλ᾽ ἰὴ μόνον λέγε."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἰὴ ἰὴ τοίνυν, ἰὴ μόνον λέγω.<br>Ἑρμῇ Χάρισιν Ὥραισιν Ἀφροδίτῃ Πόθῳ.<br>Ἄρει δέ;"}, {"st": null, "sp": "Χορός", "t": "μὴ μή."}, {"st": null, "sp": "Τρυγαῖος", "t": "μηδ᾽ Ἐνυαλίῳ γε;"}, {"st": null, "sp": "Χορός", "t": "μή."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὑπότεινε δὴ πᾶς καὶ κάταγε τοῖσιν κάλῳς."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ εἶα."}, {"st": "460", "sp": "Χορός", "t": "εἶα μάλα."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ εἶα."}, {"st": null, "sp": "Χορός", "t": "εἶα ἔτι μάλα."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ εἶα, ὦ εἶα."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οὐχ ἕλκουσ᾽ ἅνδρες ὁμοίως.<br>οὐ ξυλλήψεσθ᾽; οἷ᾽ ὀγκύλλεσθ᾽·<br>οἰμώξεσθ᾽ οἱ Βοιωτοί."}, {"st": null, "sp": "Ἑρμῆς", "t": "εἶά νυν."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἶα ὦ."}, {"st": null, "sp": "Χορός", "t": "&lt;ἀλλ᾽&gt; ἄγετε ξυνανέλκετε καὶ σφώ."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκουν ἕλκω κἀξαρτῶμαι<br>κἀπεμπίπτω καὶ σπουδάζω;"}, {"st": null, "sp": "Χορός", "t": "πῶς οὖν οὐ χωρεῖ τοὔργον;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ Λάμαχ᾽ ἀδικεῖς ἐμποδὼν καθήμενος.<br>οὐδὲν δεόμεθ᾽ ὦνθρωπε τῆς σῆς μορμόνος."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐδ᾽ οἵδε γ᾽ εἷλκον οὐδὲν ἁργεῖοι πάλαι<br>ἀλλ᾽ ἢ κατεγέλων τῶν ταλαιπωρουμένων,<br>καὶ ταῦτα διχόθεν μισθοφοροῦντες ἄλφιτα."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οἱ Λάκωνες ὦγάθ᾽ ἕλκουσ᾽ ἀνδρικῶς."}, {"st": "480", "sp": "Χορός", "t": "ἆρ᾽ οἶσθ᾽ ὅσοι γ᾽ αὐτῶν ἔχονται τοῦ ξύλου,<br>μόνοι προθυμοῦντ᾽· ἀλλ᾽ ὁ χαλκεὺς οὐκ ἐᾷ."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐδ᾽ οἱ Μεγαρῆς δρῶσ᾽ οὐδέν· ἕλκουσιν δ᾽ ὅμως<br>γλισχρότατα σαρκάζοντες ὥσπερ κυνίδια,<br>ὑπὸ τοῦ γε λιμοῦ νὴ Δἴ ἐξολωλότες."}, {"st": "485", "sp": "Τρυγαῖος", "t": "οὐδὲν ποιοῦμεν ὦνδρες· ἀλλ ὁμοθυμαδὸν<br>ἅπασιν ἡμῖν αὖθις ἀντιληπτέον."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ εἶα."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἶα μάλα."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ εἶα."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἶα νὴ Δία."}, {"st": "490", "sp": "Χορός", "t": "μικρόν γε κινοῦμεν."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκουν δεινὸν . . .<br>τοὺς μὲν τείνειν τοὺς δ᾽ ἀντισπᾶν;<br>πληγὰς λήψεσθ᾽ ὦργεῖοι."}, {"st": null, "sp": "Ἑρμῆς", "t": "εἶά νυν."}, {"st": "495", "sp": "Τρυγαῖος", "t": "εἶα ὦ."}, {"st": null, "sp": "Χορός", "t": "ὡς κακόνοι τινές εἰσιν ἐν ἡμῖν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὑμεῖς μὲν γοῦν οἱ κιττῶντες<br>τῆς εἰρήνης σπᾶτ᾽ ἀνδρείως."}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ εἴσ᾽ οἳ κωλύουσιν."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἄνδρες Μεγαρῆς οὐκ ἐς κόρακας ἐρρήσετε;<br>μισεῖ γὰρ ὑμᾶς ἡ θεὸς μεμνημένη·<br>πρῶτοι γὰρ αὐτὴν τοῖς σκορόδοις ἠλείψατε.<br>καὶ τοῖς Ἀθηναίοισι παύσασθαι λέγω<br>ἐντεῦθεν ἐχομένοις ὅθεν νῦν ἕλκετε·<br>οὐδὲν γὰρ ἄλλο δρᾶτε πλὴν δικάζετε.<br>ἀλλ᾽ εἴπερ ἐπιθυμεῖτε τήνδ᾽ ἐξελκύσαι,<br>πρὸς τὴν θάλατταν ὀλίγον ὑποχωρήσατε."}, {"st": null, "sp": "Χορός", "t": "ἄγ᾽ ὦνδρες αὐτοὶ δὴ μόνοι λαβώμεθ᾽ οἱ γεωργοί."}, {"st": null, "sp": "Ἑρμῆς", "t": "χωρεῖ γέ τοι τὸ πρᾶγμα πολλῷ μᾶλλον ὦνδρες ὑμῖν."}, {"st": "510", "sp": "Χορός", "t": "χωρεῖν τὸ πρᾶγμά φησιν· ἀλλὰ πᾶς ἀνὴρ προθυμοῦ."}, {"st": null, "sp": "Τρυγαῖος", "t": "οἵ τοι γεωργοὶ τοὔργον ἐξέλκουσι κἄλλος οὐδείς."}, {"st": null, "sp": "Χορός", "t": "ἄγε νυν ἄγε πᾶς."}, {"st": null, "sp": "Ἑρμῆς", "t": "καὶ μὴν ὁμοῦ ᾽στιν ἤδη."}, {"st": "515", "sp": "Χορός", "t": "μή νυν ἀνῶμεν ἀλλ᾽ ἐπεντείνωμεν<br>ἀνδρικώτερον."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἤδη ᾽στὶ τοῦτ᾽ ἐκεῖνο."}, {"st": null, "sp": "Χορός", "t": "ὦ εἶα νῦν, ὦ εἶα πᾶς.<br>ὦ εἶα εἶα εἶα εἶα εἶα εἶα.<br>ὦ εἶα εἶα εἶα εἶα εἶα πᾶς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ πότνια βοτρυόδωρε τί προσείπω σ᾽ ἔπος;<br>πόθεν ἂν λάβοιμι ῥῆμα μυριάμφορον<br>ὅτῳ προσείπω σ᾽; οὐ γὰρ εἶχον οἴκοθεν.<br>ὦ χαῖρ᾽ Ὀπώρα, καὶ σὺ δ᾽ ὦ Θεωρία.<br>οἷον δ᾽ ἔχεις τὸ πρόσωπον ὦ Θεωρία,<br>οἷον δὲ πνεῖς, ὡς ἡδὺ κατὰ τῆς καρδίας,<br>γλυκύτατον ὥσπερ ἀστρατείας καὶ μύρου."}, {"st": null, "sp": "Ἑρμῆς", "t": "μῶν οὖν ὅμοιον καὶ γυλιοῦ στρατιωτικοῦ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀπέπτυσ᾽ ἐχθροῦ φωτὸς ἔχθιστον πλέκος.<br>τοῦ μὲν γὰρ ὄζει κρομμυοξυρεγμίας,<br>ταύτης δ᾽ ὀπώρας, ὑποδοχῆς, Διονυσίων,<br>αὐλῶν, τραγῳδῶν, Σοφοκλέους μελῶν, κιχλῶν,<br>ἐπυλλίων Εὐριπίδου —"}, {"st": null, "sp": "Ἑρμῆς", "t": "κλαύσἄρα σὺ<br>ταύτης καταψευδόμενος· οὐ γὰρ ἥδεται<br>αὕτη ποιητῇ ῥηματίων δικανικῶν."}, {"st": null, "sp": "Τρυγαῖος", "t": "κιττοῦ, τρυγοίπου, προβατίων βληχωμένων,<br>“κόλπου” γυναικῶν διατρεχουσῶν εἰς ἀγρόν,<br>δούλης μεθυούσης, ἀνατετραμμένου χοῶς,<br>ἄλλων τε πολλῶν κἀγαθῶν —"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἴθι νυν ἄθρει<br>οἷον πρὸς ἀλλήλας λαλοῦσιν αἱ πόλεις<br>διαλλαγεῖσαι καὶ γελῶσιν ἄσμεναι,<br>καὶ ταῦτα δαιμονίως ὑπωπιασμέναι<br>ἁπαξάπασαι καὶ κυάθους προσκείμεναι."}, {"st": null, "sp": "Τρυγαῖος", "t": "καὶ τῶνδε τοίνυν τῶν θεωμένων σκόπει<br>τὰ πρόσωφ᾽, ἵνα γνῷς τὰς τέχνας."}, {"st": null, "sp": "Ἑρμῆς", "t": "αἰβοῖ τάλας,"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐκεινονὶ γοῦν τὸν λοφοποιὸν οὐχ ὁρᾷς<br>τίλλονθ᾽ ἑαυτόν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ὁ δέ γε τὰς σμινύας ποιῶν<br>κατέπαρδεν ἄρτι τοῦ ξιφουργοῦ ᾽κεινουί."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὁ δὲ δρεπανουργὸς οὐχ ὁρᾷς ὡς ἥδεται,<br>καὶ τὸν δορυξὸν οἷον ἐσκιμάλισεν;"}, {"st": "550", "sp": "Ἑρμῆς", "t": "ἴθι νυν ἄνειπε τοὺς γεωργοὺς ἀπιέναι."}, {"st": "555", "sp": "Τρυγαῖος", "t": "ἀκούετε λεῴ· τοὺς γεωργοὺς ἀπιέναι<br>τὰ γεωργικὰ σκεύη λαβόντας εἰς ἀγρὸν<br>ὡς τάχιστ᾽ ἄνευ δορατίου καὶ ξίφους κἀκοντίου·<br>ὡς ἅπαντ᾽ ἤδη ᾽στὶ μεστὰ τἀνθάδ᾽ εἰρήνης σαπρᾶς.<br>ἀλλὰ πᾶς χώρει πρὸς ἔργον εἰς ἀγρὸν παιωνίσας."}, {"st": null, "sp": "Χορός", "t": "ὦ ποθεινὴ τοῖς δικαίοις καὶ γεωργοῖς ἡμέρα,<br>ἄσμενός σ᾽ ἰδὼν προσειπεῖν βούλομαι τὰς ἀμπέλους,<br>τάς τε συκᾶς, ἃς ἐγὼ ᾽φύτευον ὢν νεώτερος,<br>ἀσπάσασθαι θυμὸς ἡμῖν ἐστι πολλοστῷ χρόνῳ."}, {"st": null, "sp": "Τρυγαῖος", "t": "νῦν μὲν οὖν ὦνδρες προσευξώμεσθα πρῶτον τῇ θεῷ,<br>ἥπερ ἡμῶν τοὺς λόφους ἀφεῖλε καὶ τὰς Γοργόνας·<br>εἶθ᾽ ὅπως Λιταργιοῦμεν οἴκαδ᾽ ἐς τὰ χωρία,<br>ἐμπολήσαντές τι χρηστὸν εἰς ἀγρὸν ταρίχιον."}, {"st": "565", "sp": "Ἑρμῆς", "t": "ὦ Πόσειδον ὡς καλὸν τὸ στῖφος αὐτῶν φαίνεται<br>καὶ πυκνὸν καὶ γοργὸν ὥσπερ μᾶζα καὶ πανδαισία."}, {"st": null, "sp": "Τρυγαῖος", "t": "νὴ Δἴ ἡ γὰρ σφῦρα λαμπρὸν ἦν ἄρ᾽ ἐξωπλισμένη,<br>αἵ τε θρίνακες διαστίλβουσι πρὸς τὸν ἥλιον.<br>ἦ καλῶς αὐτῶν ἀπαλλάξειεν ἂν μετόρχιον.<br>ὥστ᾽ ἔγωγ᾽ ἤδη ᾽πιθυμῶ καὐτὸς ἐλθεῖν εἰς ἀγρὸν<br>καὶ τριαινοῦν τῇ δικέλλῃ διὰ χρόνου τὸ γῄδιον.<br>ἀλλ᾽ ἀναμνησθέντες ὦνδρες<br>τῆς διαίτης τῆς παλαιᾶς,<br>ἣν παρεῖχ᾽ αὕτη ποθ᾽ ἡμῖν,<br>τῶν τε παλασίων ἐκείνων<br>τῶν τε σύκων τῶν τε μύρτων,<br>τῆς τρυγός τε τῆς γλυκείας<br>τῆς ἰωνιᾶς τε τῆς πρὸς<br>τῷ φρέατι τῶν τ᾽ ἐλαῶν<br>ὧν ποθοῦμεν,<br>ἀντὶ τούτων τήνδε νυνὶ<br>τὴν θεὸν προσείπατε."}, {"st": null, "sp": "Χορός", "t": "χαῖρε χαῖρ᾽, ὡς ἀσμένοισιν ἦλθες, ὦ φιλτάτη.<br>σῷ γὰρ ἐδάμην πόθῳ, δαιμόνια βουλόμενος εἰς ἀγρὸν ἀνερπύσαι<br>*<br>ἦσθα γὰρ μέγιστον ἡμῖν κέρδος ὦ ποθουμένη<br>πᾶσιν ὁπόσοι γεωργὸν βίον ἐτρίβομεν.<br>μόνη γὰρ ἡμᾶς ὠφέλεις.<br>πολλὰ γὰρ ἐπάσχομεν πρίν ποτ᾽ ἐπὶ σοῦ γλυκέα κἀδάπανα καὶ φίλα.<br>τοῖς ἀγροίκοισιν γὰρ ἦσθα χῖδρα καὶ σωτηρία.<br>ὥστε σὲ τά τ᾽ ἀμπέλια καὶ τὰ νέα συκίδια<br>τἄλλα θ᾽ ὁπόσ᾽ ἔστι φυτὰ<br>προσγελάσεται λαβόντ᾽ ἄσμενα.<br>ἀλλὰ ποῦ ποτ᾽ ἦν ἀφ᾽ ἡμῶν τὸν πολὺν τοῦτον χρόνον<br>ἥδε; τοῦθ᾽ ἡμᾶς δίδαξον ὦ θεῶν εὐνούστατε."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὦ σοφώτατοι γεωργοί, τἀμὰ δὴ ξυνίετε<br>ῥήματ᾽, εἰ βούλεσθ᾽ ἀκοῦσαι τήνδ᾽ ὅπως ἀπώλετο.<br>πρῶτα μὲν γὰρ “αὐτῆς ἦρξεν” Φειδίας πράξας κακῶς·<br>εἶτα Περικλέης φοβηθεὶς μὴ μετάσχοι τῆς τύχης,<br>τὰς φύσεις ὑμῶν δεδοικὼς καὶ τὸν αὐτοδὰξ τρόπον,<br>πρὶν παθεῖν τι δεινὸν αὐτός, ἐξέφλεξε τὴν πόλιν.<br>ἐμβαλὼν σπινθῆρα μικρὸν Μεγαρικοῦ ψηφίσματος,<br>ἐξεφύσησεν τοσοῦτον πόλεμον ὥστε τῷ καπνῷ<br>πάντας Ἕλληνας δακρῦσαι, τούς τ᾽ ἐκεῖ τούς τ᾽ ἐνθάδε.<br>ὡς δ᾽ ἅπαξ “τὸ πρῶτον ἄκουσ᾽” ἐψόφησεν ἄμπελος<br>καὶ πίθος πληγεὶς ὑπ᾽ ὀργῆς ἀντελάκτισεν πίθῳ,<br>οὐκέτ᾽ ἦν οὐδεὶς ὁ παύσων, ἥδε δ᾽ ἠφανίζετο."}, {"st": null, "sp": "Τρυγαῖος", "t": "ταῦτα τοίνυν μὰ τὸν Ἀπόλλω ᾽γὼ ᾽πεπύσμην οὐδενός,<br>οὐδ᾽ ὅπως αὐτῇ προσήκοι Φειδίας ἠκηκόη."}, {"st": null, "sp": "Χορός", "t": "οὐδ᾽ ἔγωγε πλήν γε νυνί. ταῦτ᾽ ἄρ᾽ εὐπρόσωπος ἦν,<br>οὖσα συγγενὴς ἐκείνου. πολλά γ᾽ ἡμᾶς λανθάνει."}, {"st": null, "sp": "Ἑρμῆς", "t": "κᾆτ᾽ ἐπειδὴ ᾽γνωσαν ὑμᾶς αἱ πόλεις ὧν ἤρχετε<br>ἠγριωμένους ἐπ᾽ ἀλλήλοισι καὶ σεσηρότας,<br>πάντ᾽ ἐμηχανῶντ᾽ ἐφ᾽ ὑμῖν τοὺς φόρους φοβούμεναι,<br>κἀνέπειθον τῶν Λακώνων τοὺς μεγίστους χρήμασιν.<br>οἱ δ᾽ ἅτ᾽ ὄντες αἰσχροκερδεῖς καὶ διειρωνόξενοι<br>τήνδ᾽ ἀπορρίψαντες αἰσχρῶς τὸν πόλεμον ἀνήρπασαν·<br>κᾆτα τἀκείνων γε κέρδη τοῖς γεωργοῖς ἦν κακά·<br>αἱ γὰρ ἐνθένδ᾽ αὖ τριήρεις ἀντιτιμωρούμεναι<br>οὐδὲν αἰτίων ἂν ἀνδρῶν τὰς κράδας κατήσθιον."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐν δίκῃ μὲν οὖν, ἐπεί τοι τὴν κορώνεών γέ μου<br>ἐξέκοψαν, ἣν ἐγὼ ᾽φύτευσα κἀξεθρεψάμην."}, {"st": null, "sp": "Χορός", "t": "νὴ Δί᾽ ὦ μέλ᾽ ἐνδίκως &lt;γε&gt; δῆτ᾽, ἐπεὶ κἀμοῦ λίθον<br>ἐμβαλόντες ἑξμέδιμνον κυψέλην ἀπώλεσαν."}, {"st": null, "sp": "Ἑρμῆς", "t": "κᾆτα δ᾽ ὡς ἐκ τῶν ἀγρῶν ξυνῆλθεν οὑργάτης λεώς,<br>τὸν τρόπον πωλούμενος τὸν αὐτὸν οὐκ ἐμάνθανεν,<br>ἀλλ᾽ ἅτ᾽ ὢν ἄνευ γιγάρτων καὶ φιλῶν τὰς ἰσχάδας<br>ἔβλεπεν πρὸς τοὺς λέγοντας· οἱ δὲ γιγνώσκοντες εὖ<br>τοὺς πένητας ἀσθενοῦντας κἀποροῦντας ἀλφίτων,<br>τήνδε μὲν δικροῖς ἐώθουν τὴν θεὸν κεκράγμασιν,<br>πολλάκις φανεῖσαν αὐτὴν τῆσδε τῆς χώρας πόθῳ,<br>τῶν δὲ συμμάχων ἔσειον τοὺς παχεῖς καὶ πλουσίους,<br>αἰτίας ἂν προστιθέντες, ὡς φρονεῖ τὰ Βρασίδου.<br>εἶτ᾽ ἂν ὑμεῖς τοῦτον ὥσπερ κυνίδι᾽ ἐσπαράττετε·<br>ἡ πόλις γὰρ ὠχριῶσα κἀν φόβῳ καθημένη,<br>ἅττα διαβάλοι τις αὐτῇ, ταῦτ᾽ ἂν ἥδιστ᾽ ἤσθιεν.<br>οἳ δὲ τὰς πληγὰς ὁρῶντες ἃς ἐτύπτονθ᾽ οἱ ξένοι<br>χρυσίῳ τῶν ταῦτα ποιούντων ἐβύνουν τὸ στόμα,<br>ὥστ᾽ ἐκείνους μὲν ποιῆσαι πλουσίους, ἡ δ᾽ Ἑλλὰς ἂν<br>ἐξερημωθεῖσ᾽ ἂν ὑμᾶς ἔλαθε. ταῦτα δ᾽ ἦν ὁ δρῶν<br>βυρσοπώλης."}, {"st": null, "sp": "Τρυγαῖος", "t": "παῦε παῦ᾽ ὦ δέσποθ᾽ Ἑρμῆ, μὴ λέγε,<br>ἀλλ᾽ ἔα τὸν ἄνδρ᾽ ἐκεῖνον οὗπερ ἔστ᾽ εἶναι κάτω·<br>οὐ γὰρ ἡμέτερος ἔτ᾽ ἔστ᾽ ἐκεῖνος ἁνὴρ ἀλλὰ σός.<br>ἅττ᾽ ἂν οὖν λέγῃς ἐκεῖνον,<br>κεἰ πανοῦργος ἦν, ὅτ᾽ ἔζη,<br>καὶ λάλος καὶ συκοφάντης<br>καὶ κύκηθρον καὶ τάρακτρον,<br>ταῦθ᾽ ἁπαξάπαντα νυνὶ<br>τοὺς σεαυτοῦ λοιδορεῖς.<br>ἀλλ᾽ ὅ τι σιωπᾷς ὦ πότνια κάτειπέ μοι."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀλλ᾽ οὐκ ἂν εἴποι πρός γε τοὺς θεωμένους·<br>ὀργὴν γὰρ αὐτοῖς ὧν ἔπαθε πολλὴν ἔχει."}, {"st": "660", "sp": "Τρυγαῖος", "t": "ἡ δ᾽ ἀλλὰ πρὸς σὲ μικρὸν εἰπάτω μόνον."}, {"st": null, "sp": "Ἑρμῆς", "t": "εἴφ᾽ ὅ τι νοεῖς αὐτοῖσι πρὸς ἔμ᾽ ὦ φιλτάτη.<br>ἴθ᾽ ὦ γυναικῶν μισοπορπακιστάτη.<br>εἶεν, ἀκούω. ταῦτ᾽ ἐπικαλεῖς; μανθάνω.<br>ἀκούσαθ᾽ ὑμεῖς ὧν ἕνεκα μομφὴν ἔχει.<br>ἐλθοῦσά φησιν αὐτομάτη μετὰ τἀν Πύλῳ<br>σπονδῶν φέρουσα τῇ πόλει κίστην πλέαν<br>ἀποχειροτονηθῆναι τρὶς ἐν τἠκκλησίᾳ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἡμάρτομεν ταῦτ᾽· ἀλλὰ συγγνώμην ἔχε·<br>ὁ νοῦς γὰρ ἡμῶν ἦν τότ᾽ ἐν τοῖς σκύτεσιν."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἴθι νυν ἄκουσον οἷον ἄρτι μ᾽ ἤρετο,<br>ὅστις κακόνους αὐτῇ μάλιστ᾽ ἦν ἐνθάδε,<br>χὤστις φίλος κἄσπευδεν εἶναι μὴ μάχας."}, {"st": null, "sp": "Τρυγαῖος", "t": "εὐνούστατος μὲν ἦν μακρῷ Κλεώνυμος."}, {"st": "675", "sp": "Ἑρμῆς", "t": "ποῖός τις οὖν εἶναι δοκεῖ τὰ πολεμικὰ<br>ὁ Κλεώνυμος;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ψυχήν γ᾽ ἄριστος πλήν γ᾽ ὅτι<br>οὐκ ἦν ἄρ᾽ οὗπέρ φησιν εἶναι τοῦ πατρός.<br>εἰ γάρ ποτ᾽ ἐξέλθοι στρατιώτης, εὐθέως<br>ἀποβολιμαῖος τῶν ὅπλων ἐγίγνετο."}, {"st": "680", "sp": "Ἑρμῆς", "t": "ἔτι νῦν ἄκουσον οἷον ἄρτι μ᾽ ἤρετο,<br>ὅστις κρατεῖ νῦν τοῦ λίθου τοῦ ᾽ν τῇ πυκνί."}, {"st": null, "sp": "Τρυγαῖος", "t": "Ὑπέρβολος νῦν τοῦτ᾽ ἔχει τὸ χωρίον.<br>αὕτη τί ποιεῖς; τὴν κεφαλὴν ποῖ περιάγεις;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀποστρέφεται τὸν δῆμον ἀχθεσθεῖσ᾽ ὅτι<br>αὑτῷ πονηρὸν προστάτην ἐπεγράψατο."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οὐκέτ᾽ αὐτῷ χρησόμεθ᾽ οὐδέν, ἀλλὰ νῦν<br>ἀπορῶν ὁ δῆμος ἐπιτρόπου καὶ γυμνὸς ὢν<br>τοῦτον τέως τὸν ἄνδρα περιεζώσατο."}, {"st": null, "sp": "Ἑρμῆς", "t": "πῶς οὖν ξυνοίσει ταῦτ᾽ ἐρωτᾷ τῇ πόλει."}, {"st": null, "sp": "Τρυγαῖος", "t": "εὐβουλότεροι γενησόμεθα."}, {"st": null, "sp": "Ἑρμῆς", "t": "τρόπῳ τίνι;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅτι τυγχάνει λυχνοποιὸς ὤν. πρὸ τοῦ μὲν οὖν<br>ἐψηλαφῶμεν ἐν σκότῳ τὰ πράγματα,<br>νυνὶ δ᾽ ἅπαντα πρὸς λύχνον βουλεύσομεν."}, {"st": null, "sp": "Ἑρμῆς", "t": "ὢ ὤ,<br>οἷά μ᾽ ἐκέλευσεν ἀναπυθέσθαι σου."}, {"st": null, "sp": "Τρυγαῖος", "t": "τὰ τί;"}, {"st": "695", "sp": "Ἑρμῆς", "t": "πάμπολλα καὶ τἀρχαῖ᾽ ἃ κατέλιπεν τότε·<br>πρῶτον δ᾽ ὅ τι πράττει Σοφοκλέης ἀνήρετο."}, {"st": null, "sp": "Τρυγαῖος", "t": "εὐδαιμονεῖ, πάσχει δὲ θαυμαστόν."}, {"st": null, "sp": "Ἑρμῆς", "t": "τὸ τί;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐκ τοῦ Σοφοκλέους γίγνεται Σιμωνίδης."}, {"st": null, "sp": "Ἑρμῆς", "t": "Σιμωνίδης; πῶς;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅτι γέρων ὢν καὶ σαπρὸς<br>κέρδους ἕκατι κἂν ἐπὶ ῥιπὸς πλέοι."}, {"st": "700", "sp": "Ἑρμῆς", "t": "τί δαί; Κρατῖνος ὁ σοφὸς ἔστιν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀπέθανεν<br>ὅθ᾽ οἱ Λάκωνες ἐνέβαλον."}, {"st": null, "sp": "Ἑρμῆς", "t": "τί παθών;"}, {"st": "705", "sp": "Τρυγαῖος", "t": "ὅ τι;<br>ὼρακιάσας· οὐ γὰρ ἐξηνέσχετο<br>ἰδὼν πίθον καταγνύμενον οἴνου πλέων.<br>χἄτερα πόσ᾽ ἄττ᾽ οἴει γεγενῆσθ᾽ ἐν τῇ πόλει;<br>ὥστ᾽ οὐδέποτ᾽ ὦ δέσποιν᾽ ἀφησόμεσθά σου."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἴθι νυν ἐπὶ τούτοις τὴν Ὀπώραν λάμβανε<br>γυναῖκα σαυτῷ τήνδε· κᾆτ᾽ ἐν τοῖς ἀγροῖς<br>ταύτῃ ξυνοικῶν ἐκποιοῦ σαυτῷ βότρυς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ φιλτάτη δεῦρ᾽ ἐλθὲ καὶ δός μοι κύσαι.<br>ἆρ᾽ ἂν βλαβῆναι διὰ χρόνου τί σοι δοκῶ<br>ὦ δέσποθ᾽ Ἑρμῆ τῆς Ὀπώρας κατελάσας;"}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐκ εἴ γε κυκεῶν᾽ ἐπιπίοις βληχωνίαν.<br>ἀλλ᾽ ὡς τάχιστα τήνδε τὴν Θεωρίαν<br>ἀπάγαγε τῇ βουλῇ λαβών, ἧσπέρ ποτ᾽ ἦν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ μακαρία βουλὴ σὺ τῆς Θεωρίας,<br>ὅσον ῥοφήσει ζωμὸν ἡμερῶν τριῶν,<br>ὅσας δὲ κατέδει ξόλικας ἑφθὰς καὶ κρέα.<br>ἀλλ᾽ ὦ φίλ᾽ Ἑρμῆ χαῖρε πολλά."}, {"st": null, "sp": "Ἑρμῆς", "t": "·καὶ σύ γε<br>ὦνθρωπε χαίρων ἄπιθι καὶ μέμνησό μου."}, {"st": "720", "sp": "Τρυγαῖος", "t": "ὦ κάνθαρ᾽ οἴκαδ᾽ οἴκαδ᾽ ἀποπετώμεθα."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐκ ἐνθάδ᾽ ὦ τᾶν ἔστι."}, {"st": null, "sp": "Τρυγαῖος", "t": "ποῖ γὰρ οἴχεται;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ὑφ᾽ ἅρματ᾽ ἐλθὼν Ζηνὸς ἀστραπηφορεῖ."}, {"st": null, "sp": "Τρυγαῖος", "t": "πόθεν οὖν ὁ τλήμων ἐνθάδ᾽ ἕξει σιτία;"}, {"st": null, "sp": "Ἑρμῆς", "t": "τὴν τοῦ Γανυμήδους ἀμβροσίαν σιτήσεται."}, {"st": "725", "sp": "Τρυγαῖος", "t": "πῶς δῆτ᾽ ἐγὼ καταβήσομαι;"}, {"st": null, "sp": "Ἑρμῆς", "t": "θάρρει, καλῶς·<br>τῃδὶ παρ᾽ αὐτὴν τὴν θεόν."}, {"st": null, "sp": "Τρυγαῖος", "t": "δεῦρ᾽ ὦ κόραι<br>ἕπεσθον ἅμ᾽ ἐμοὶ θᾶττον, ὡς πολλοὶ πάνυ<br>ποθοῦντες ὑμᾶς ἀναμένουσ᾽ ἐστυκότες."}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ ἴθι χαίρων· ἡμεῖς δὲ τέως τάδε τὰ σκεύη παραδόντες<br>τοῖς ἀκολούθοις δῶμεν σῴζειν, ὡς εἰώθασι μάλιστα<br>περὶ τὰς σκηνὰς πλεῖστοι κλέπται κυπτάζειν καὶ κακοποιεῖν.<br>ἀλλὰ φυλάττετε ταῦτ᾽ ἀνδρείως· ἡμεῖς δ᾽ αὖ τοῖσι θεαταῖς<br>ἣν ἔχομεν ὁδὸν λόγων εἴπωμεν ὅσα τε νοῦς ἔχει.<br>Χορός<br>χρῆν μὲν τύπτειν τοὺς ῥαβδούχους, εἴ τις κωμῳδοποιητὴς<br>αὑτὸν ἐπῄνει πρὸς τὸ θέατρον παραβὰς ἐν τοῖς ἀναπαίστοις·<br>εἰ δ᾽ οὖν εἰκός τινα τιμῆσαι, θύγατερ Διός, ὅστις ἄριστος<br>κωμῳδοδιδάσκαλος ἀνθρώπων καὶ κλεινότατος γεγένηται,<br>ἄξιος εἶναί φησ᾽ εὐλογίας μεγάλης ὁ διδάσκαλος ἡμῶν.<br>πρῶτον μὲν γὰρ τοὺς ἀντιπάλους μόνος ἀνθρώπων κατέπαυσεν<br>ἐς τὰ ῥάκια σκώπτοντας ἀεὶ καὶ τοῖς φθειρσὶν πολεμοῦντας,<br>τούς θ᾽ Ἡρακλέας τοὺς μάττοντας καὶ τοὺς πεινῶντας ἐκείνους<br>ἐξήλασ᾽ ἀτιμώσας πρῶτος, καὶ τοὺς δούλους παρέλυσεν<br>τοὺς φεύγοντας κἀξαπατῶντας καὶ τυπτομένους ἐπίτηδες,<br>οὓς ἐξῆγον κλάοντας ἀεί, καὶ τούτους οὕνεκα τουδί,<br>ἵν᾽ ὁ σύνδουλος σκώψας αὐτοῦ τὰς πληγὰς εἶτ᾽ ἀνέροιτο,<br>“ὦ κακόδαιμον τί τὸ δέρμ᾽ ἔπαθες; μῶν ὑστριχὶς εἰσέβαλέν σοι<br>ἐς τὰς πλευρὰς πολλῇ στρατιᾷ κἀδενδροτόμησε τὸ νῶτον;”<br>τοιαῦτ᾽ ἀφελὼν κακὰ καὶ φόρτον καὶ βωμολοχεύματ᾽ ἀγεννῆ<br>ἐποίησε τέχνην μεγάλην ἡμῖν κἀπύργωσ᾽ οἰκοδομήσας<br>ἔπεσιν μεγάλοις καὶ διανοίαις καὶ σκώμμασιν οὐκ ἀγοραίοις,<br>οὐκ ἰδιώτας ἀνθρωπίσκους κωμῳδῶν οὐδὲ γυναῖκας,<br>ἀλλ᾽ Ἡρακλέους ὀργήν τιν᾽ ἔχων τοῖσι μεγίστοις ἐπεχείρει,<br>διαβὰς βυρσῶν ὀσμὰς δεινὰς κἀπειλὰς βορβοροθύμους,<br>καὶ πρῶτον μὲν μάχομαι πάντων αὐτῷ τῷ καρχαρόδοντι,<br>οὗ δεινόταται μὲν ἀπ᾽ ὀφθαλμῶν Κύννης ἀκτῖνες ἔλαμπον,<br>ἑκατὸν δὲ κύκλῳ κεφαλαὶ κολάκων οἰμωξομένων ἐλιχμῶντο<br>περὶ τὴν κεφαλήν, φωνὴν δ᾽ εἶχεν χαράδρας ὄλεθρον τετοκυίας,<br>φώκης δ᾽ ὀσμήν, Λαμίας ὄρχεις ἀπλύτους, πρωκτὸν δὲ καμήλου.<br>τοιοῦτον ἰδὼν τέρας οὐ κατέδεισ᾽, ἀλλ᾽ ὑπὲρ ὑμῶν πολεμίζων<br>ἀντεῖχον ἀεὶ καὶ τῶν ἄλλων νήσων. ὧν οὕνεκα νυνὶ<br>ἀποδοῦναί μοι τὴν χάριν ὑμᾶς εἰκὸς καὶ μνήμονας εἶναι.<br>καὶ γὰρ πρότερον πράξας κατὰ νοῦν οὐχὶ παλαίστρας περινοστῶν<br>παῖδας ἐπείρων, ἀλλ᾽ ἀράμενος τὴν σκευὴν εὐθὺς ἐχώρουν,<br>παῦρ᾽ ἀνιάσας, πόλλ᾽ εὐφράνας, πάντα παρασχὼν τὰ δέοντα."}, {"st": null, "sp": "Χορός", "t": "πρὸς ταῦτα χρεὼν εἶναι μετ᾽ ἐμοῦ<br>καὶ τοὺς ἄνδρας καὶ τοὺς παῖδας·<br>καὶ τοῖς φαλακροῖσι παραινοῦμεν<br>ξυσπουδάζειν περὶ τῆς νίκης.<br>πᾶς γάρ τις ἐρεῖ νικῶντος ἐμοῦ<br>κἀπὶ τραπέζῃ καὶ ξυμποσίοις,<br>“φέρε τῷ φαλακρῷ, δὸς τῷ φαλακρῷ<br>τῶν τρωγαλίων, καὶ μἀφαίρει<br>γενναιοτάτου τῶν ποιητῶν<br>ἀνδρὸς τὸ μέτωπον ἔχοντος”."}, {"st": "795", "sp": "Χορός", "t": "Μοῦσα σὺ μὲν πολέμους ἀπωσαμένη μετ᾽ ἐμοῦ<br>τοῦ φίλου χόρευσον,<br>κλείουσα θεῶν τε γάμους ἀνδρῶν τε δαῖτας<br>καὶ θαλίας μακάρων· σοὶ γὰρ τάδ᾽ ἐξ ἀρχῆς μέλει.<br>ἢν δέ σε Καρκίνος ἐλθὼν<br>ἀντιβολῇ μετὰ τῶν παίδων χορεῦσαι,<br>μήθ᾽ ὑπάκουε μήτ᾽ ἔλθῃς<br>συνέριθος αὐτοῖς,<br>ἀλλὰ νόμιζε πάντας<br>ὄρτυγας οἰκογενεῖς γυλιαύχενας ὀρχηστὰς<br>ναννοφυεῖς σφυράδων ἀποκνίσματα μηχανοδίφας.<br>καὶ γὰρ ἔφασχ᾽ ὁ πατὴρ ὃ παρ᾽ ἐλπίδας<br>εἶχε τὸ δρᾶμα γαλῆν τῆς ἑσπέρας ἀπάγξαι."}, {"st": null, "sp": "Χορός", "t": "τοιάδε χρὴ Χαρίτων δαμώματα καλλικόμων<br>τὸν σοφὸν ποιητὴν<br>ὑμνεῖν, ὅταν ἠρινὰ μὲν φωνῇ χελιδὼν<br>ἑζομένη κελαδῇ, χορὸν δὲ μὴ ᾽χῃ Μόρσιμος<br>μηδὲ Μελάνθιος, οὗ δὴ<br>πικροτάτην ὄπα γηρύσαντος ἤκουσ᾽<br>ἡνίκα τῶν τραγῳδῶν<br>τὸν χορὸν εἶχον ἁδελφός<br>τε και αὐτός, ἄμφω<br>Γοργόνες ὀψοφάγοι βατιδοσκόποι Ἅρπυιαι,<br>γραοσόβαι μιαροὶ τραγομάσχαλοι ἰχθυολῦμαι·<br>ὧν καταχρεμψαμένη μέγα καὶ πλατὺ<br>Μοῦσα θεὰ μετ᾽ ἐμοῦ ξύμπαιζε τὴν ἑορτήν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὡς χαλεπὸν ἐλθεῖν ἦν ἄρ᾽ εὐθὺ τῶν θεῶν.<br>ἔγωγέ τοι πεπόνηκα κομιδῇ τὼ σκέλει.<br>μικροὶ δ᾽ ὁρᾶν ἄνωθεν ἦστ᾽. ἔμοιγέ τοι<br>ἀπὸ τοὐρανοῦ ᾽φαίνεσθε κακοήθεις πάνυ,<br>ἐντευθενὶ δὲ πολύ τι κακοηθέστεροι."}, {"st": null, "sp": "Οἰκέτης", "t": "ὦ δέσποθ᾽ ἥκεις;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὡς ἐγὼ ᾽πυθόμην τινός."}, {"st": "825", "sp": "Οἰκέτης", "t": "τί δ᾽ ἔπαθες;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἤλγουν τὼ σκέλει μακρὰν ὁδὸν<br>διεληλυθώς."}, {"st": null, "sp": "Οἰκέτης", "t": "ἴθι νυν κάτειπέ μοι —"}, {"st": null, "sp": "Τρυγαῖος", "t": "τὸ τί;"}, {"st": null, "sp": "Οἰκέτης", "t": "ἄλλον τιν᾽ εἶδες ἄνδρα κατὰ τὸν ἀέρα<br>πλανώμενον πλὴν σαυτόν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκ, εἰ μή γέ που<br>ψυχὰς δύ᾽ ἢ τρεῖς διθυραμβοδιδασκάλων."}, {"st": "830", "sp": "Οἰκέτης", "t": "τί δ᾽ ἔδρων;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ξυνελέγοντ᾽ ἀναβολὰς ποτώμεναι<br>τὰς ἐνδιαεριαυερινηχέτους τινάς."}, {"st": null, "sp": "Οἰκέτης", "t": "οὐκ ἦν ἄρ᾽ οὐδ᾽ ἃ λέγουσι, κατὰ τὸν ἀέρα<br>ὡς ἀστέρες γιγνόμεθ᾽, ὅταν τις ἀποθάνῃ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "μάλιστα."}, {"st": null, "sp": "Οἰκέτης", "t": "καὶ τίς ἐστιν ἀστὴρ νῦν ἐκεῖ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "Ἴων ὁ Χῖος, ὅσπερ ἐποίησεν πάλαι<br>ἐνθάδε τὸν ἀοῖόν ποθ᾽· ὡς δ᾽ ἦλθ᾽, εὐθέως<br>ἀοῖον αὐτὸν πάντες ἐκάλουν ἀστέρα."}, {"st": null, "sp": "Οἰκέτης", "t": "τίνες γάρ εἰσ᾽ οἱ διατρέχοντες ἀστέρες,<br>οἳ καόμενοι θέουσιν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀπὸ δείπνου τινὲς<br>τῶν πλουσίων οὗτοι βαδίζουσ᾽ ἀστέρων,<br>ἰπνοὺς ἔχοντες, ἐν δὲ τοῖς ἰπνοῖσι πῦρ.<br>ἀλλ᾽ εἴσαγ᾽ ὡς τάχιστα ταυτηνὶ λαβών,<br>καὶ τὴν πύελον κατάκλυζε καὶ θέρμαιν᾽ ὕδωρ,<br>στόρνυ τ᾽ ἐμοὶ καὶ τῇδε κουρίδιον λέχος.<br>καὶ ταῦτα δράσας ἧκε δεῦρ᾽ αὖθις πάλιν·<br>ἐγὼ δ᾽ ἀποδώσω τήνδε τῇ βουλῇ τέως."}, {"st": null, "sp": "Οἰκέτης", "t": "πόθεν δ᾽ ἔλαβες ταύτας;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὁπόθεν; ἐκ τοὐρανοῦ."}, {"st": null, "sp": "Οἰκέτης", "t": "οὐκ ἂν ἔτι δοίην τῶν θεῶν τριώβολον,<br>εἰ πορνοβοσκοῦσ᾽ ὥσπερ ἡμεῖς οἱ βροτοί."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκ, ἀλλὰ κἀκεῖ ζῶσιν ἀπὸ τούτων τινές.<br>ἄγε νυν ἴωμεν."}, {"st": null, "sp": "Οἰκέτης", "t": "εἰπέ μοι, δῶ καταφαγεῖν<br>ταύτῃ τι;"}, {"st": null, "sp": "Τρυγαῖος", "t": "μηδέν· οὐ γὰρ ἐθελήσει θαγεῖν<br>οὔτ᾽ ἄρτον οὔτε μᾶζαν, εἰωθυῖ᾽ ἀεὶ<br>παρὰ τοῖς θεοῖσιν ἀμβροσίαν λείχειν ἄνω."}, {"st": "855", "sp": "Οἰκέτης", "t": "λείχειν ἄρ᾽ αὐτῇ κἀνθάδε σκευαστέον."}, {"st": null, "sp": "Χορός", "t": "εὐδαιμονικῶς γ᾽ ὁ πρεσβύτης,<br>ὅσα γ᾽ ὧδ᾽ ἰδεῖν,<br>τὰ νῦν τάδε πράττει."}, {"st": null, "sp": "Τρυγαῖος", "t": "τί δῆτ᾽ ἐπειδὰν νυμφίον μ᾽ ὁρᾶτε λαμπρὸν ὄντα;"}, {"st": null, "sp": "Χορός", "t": "ζηλωτὸς ἔσει, γέρον,<br>αὖθις νέος ὢν πάλιν,<br>μύρῳ κατάλειπτος."}, {"st": null, "sp": "Τρυγαῖος", "t": "οἶμαι. τί δῆθ᾽ ὅταν ξυνὼν τῶν τιτθίων ἔχωμαι;"}, {"st": null, "sp": "Χορός", "t": "εὐδαιμονέστερος φανεῖ τῶν Καρκίνου στροβίλων."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκουν δικαίως; ὅστις εἰς<br>ὄχημα κανθάρου ᾽πιβὰς<br>ἔσωσα τοὺς Ἕλληνας, ὥστ᾽<br>ἐν τοῖς ἀγροῖσιν αὐτοὺς<br>ἅπαντας ὄντας ἀσφαλῶς<br>βινεῖν τε καὶ καθεύδειν."}, {"st": "870", "sp": "Οἰκέτης", "t": "ἡ παῖς λέλουται καὶ τὰ τῆς πυγῆς καλά·<br>ὁ πλακοῦς πέπεπται, σησαμῆ ξυμπλάττεται.<br>καὶ τἄλλ᾽ ἁπαξάπαντα· τοῦ πέους δὲ δεῖ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἴθι νυν ἀποδῶμεν τήνδε τὴν Θεωρίαν<br>ἀνύσαντε τῇ βουλῇ."}, {"st": null, "sp": "Οἰκέτης", "t": "τίς αὑτηί;"}, {"st": null, "sp": "Τρυγαῖος", "t": "τί φῄς;<br>αὕτη Θεωρία ᾽στίν."}, {"st": null, "sp": "Οἰκέτης", "t": "ἣν ἡμεῖς ποτε<br>ἐπαίομεν Βραυρωνάδ᾽ ὑποπεπωκότες;"}, {"st": "875", "sp": "Τρυγαῖος", "t": "σάφ᾽ ἴσθι, κἀλήφθη γε μόλις."}, {"st": null, "sp": "Οἰκέτης", "t": "ὦ δέσποτα<br>ὅσην ἔχει τὴν πρωκτοπεντετηρίδα."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἶεν, τίς ἐσθ᾽ ὑμῶν δίκαιος, τίς ποτε;<br>τίς διαφυλάξει τήνδε τῇ βουλῇ λαβών;<br>οὗτος τί περιγράφεις;"}, {"st": "880", "sp": "Οἰκέτης", "t": "τὸ δεῖν᾽ εἰς Ἴσθμια<br>σκηνὴν ἐμαυτοῦ τῷ πέει καταλαμβάνω."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔπω λέγεθ᾽ ὑμεῖς τίς ὁ φυλάξων. δεῦρο σύ·<br>καταθήσομαι γὰρ αὐτὸς ἐς μέσους ἄγων."}, {"st": null, "sp": "Οἰκέτης", "t": "ἐκεινοσὶ νεύει."}, {"st": null, "sp": "Τρυγαῖος", "t": "τίς;"}, {"st": null, "sp": "Οἰκέτης", "t": "ὅστις; Ἀριφράδης,<br>ἄγειν παρ᾽ αὑτὸν ἀντιβολῶν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὦ μέλε<br>τὸν ζωμὸν αὐτῆς προσπεσὼν ἐκλάψεται.<br>ἄγε δὴ σὺ κατάθου πρῶτα τὰ σκεύη χαμαί.<br>βουλή, πρυτάνεις, ὁρᾶτε τὴν Θεωρίαν.<br>σκέψασθ᾽ ὅσ᾽ ὑμῖν ἀγαθὰ παραδώσω φέρων,<br>ὥστ᾽ εὐθέως ἄραντας ὑμᾶς τὼ σκέλει<br>ταύτης μετέωρα καταγαγεῖν ἀνάρρυσιν.<br>τουτὶ δ᾽ ὁρᾶτ᾽ ὀπτάνιον ἡμῖν ὡς καλόν."}, {"st": null, "sp": "Οἰκέτης", "t": "διὰ ταῦτα καὶ κεκάπνικ᾽ ἄρ᾽· ἐνταυθοῖ γὰρ &lt;οὖν&gt;<br>πρὸ τοῦ πολέμου τὰ λάσανα τῇ βουλῇ ποτ᾽ ἦν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἔπειτ᾽ ἀγῶνά γ᾽ εὐθὺς ἐξέσται ποιεῖν<br>ταύτην ἔχουσιν αὔριον καλὸν πάνυ,<br>ἐπὶ γῆς παλαίειν, τετραποδηδὸν ἑστάναι,<br>πλαγίαν καταβάλλειν, ἐς γόνατα κύβδ᾽ ἑστάναι,<br>καὶ παγκράτιόν γ᾽ ὑπαλειψαμένοις νεανικῶς<br>παίειν ὀρύττειν πὺξ ὁμοῦ καὶ τῷ πέει·<br>τρίτῃ δὲ μετὰ ταῦθ᾽ ἱπποδρομίαν ἄξετε,<br>ἵνα δὴ κέλης κέλητα παρακελητιεῖ,<br>ἅρματα δ᾽ ἐπ᾽ ἀλλήλοισιν ἀνατετραμμένα<br>φυσῶντα καὶ πνέοντα προσκινήσεται·<br>ἕτεροι δὲ κείσονταί γ᾽ ἀπεψωλημένοι<br>περὶ ταῖσι καμπαῖς ἡνίοχοι πεπτωκότες.<br>ἀλλ᾽ ὦ πρυτάνεις δέχεσθε τὴν Θεωρίαν.<br>θέασ᾽ ὡς προθύμως ὁ πρύτανις παρεδέξατο.<br>ἀλλ᾽ οὐκ ἂν εἴ τι προῖκα προσαγαγεῖν σ᾽ ἔδει,<br>ἀλλ᾽ ηὗρον ἄν σ᾽ ὑπέχοντα τὴν ἐκεχειρίαν."}, {"st": null, "sp": "Χορός", "t": "ἦ χρηστὸς ἀνὴρ πολίτης<br>ἐστὶν ἅπασιν ὅστις<br>γ᾽ ἐστὶ τοιοῦτος."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅταν τρυγᾶτ᾽, εἴσεσθε πολλῷ μᾶλλον οἷός εἰμι."}, {"st": "915", "sp": "Χορός", "t": "καὶ νῦν σύ γε δῆλος εἶ·<br>σωτὴρ γὰρ ἅπασιν ἀνθρώποις<br>γεγένησαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "φήσεις ἐπειδὰν ἐκπίῃς οἴνου νέου λεπαστήν."}, {"st": null, "sp": "Χορός", "t": "καὶ πλήν γε τῶν θεῶν ἀεί σ᾽ ἡγησόμεσθα πρῶτον."}, {"st": null, "sp": "Τρυγαῖος", "t": "πολλῶν γὰρ ὑμῖν ἄξιος<br>Τρυγαῖος ἁθμονεὺς ἐγώ,<br>δεινῶν ἀπαλλάξας πόνων<br>τὸν δημότην ὅμιλον,<br>καὶ τὸν γεωργικὸν λεὼν<br>Ὑπέρβολόν τε παύσας."}, {"st": null, "sp": "Οἰκέτης", "t": "ἄγε δὴ τί νῷν ἐντευθενὶ ποιητέον;"}, {"st": null, "sp": "Τρυγαῖος", "t": "τί δ᾽ ἄλλο γ᾽ ἢ ταύτην χύτραις ἱδρυτέον;"}, {"st": null, "sp": "Χορός", "t": "χύτραισιν, ὥσπερ μεμφόμενον Ἑρμῄδιον;"}, {"st": "925", "sp": "Τρυγαῖος", "t": "τί δαὶ δοκεῖ; βούλεσθε λαρινῷ βοΐ;"}, {"st": null, "sp": "Χορός", "t": "βοΐ; μηδαμῶς, ἵνα μὴ βοηθεῖν ποι δέῃ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὑὶ παχείᾳ καὶ μεγάλῃ;"}, {"st": null, "sp": "Χορός", "t": "μὴ μή."}, {"st": null, "sp": "Τρυγαῖος", "t": "τιή;"}, {"st": null, "sp": "Χορός", "t": "ἵνα μὴ γένηται Θεογένους ὑηνία."}, {"st": null, "sp": "Τρυγαῖος", "t": "τῷ δὴ δοκεῖ σοι δῆτα τῶν λοιπῶν;"}, {"st": null, "sp": "Χορός", "t": "ὀί."}, {"st": "930", "sp": "Τρυγαῖος", "t": "ὀί;"}, {"st": null, "sp": "Χορός", "t": "ναὶ μὰ Δί᾽."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλὰ τοῦτό γ᾽ ἔστ᾽ Ἰωνικὸν<br>τὸ ῥῆμ᾽."}, {"st": null, "sp": "Χορός", "t": "ἐπίτηδές γ᾽, ἵν᾽ &lt;ὅταν&gt; ἐν τἠκκλησίᾳ<br>ὡς χρὴ πολεμεῖν λέγῃ τις, οἱ καθήμενοι<br>ὑπὸ τοῦ δέους λέγωσ᾽ Ἰωνικῶς ὀὶ —"}, {"st": null, "sp": "Τρυγαῖος", "t": "εὖ τοι λέγεις."}, {"st": null, "sp": "Χορός", "t": "καὶ τἄλλα γ᾽ ὦσιν ἤπιοι.<br>ὥστ᾽ ἐσόμεθ᾽ ἀλλήλοισιν ἀμνοὶ τοὺς τρόπους<br>καὶ τοῖσι συμμάχοισι πρᾳότεροι πολύ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἴθι νυν ἄγ᾽ ὡς τάχιστα τὸ πρόβατον λαβών·<br>ἐγὼ δὲ ποριῶ βωμὸν ἐφ᾽ ὅτου θύσομεν."}, {"st": null, "sp": "Χορός", "t": "ὡς πάνθ᾽ ὅσ᾽ ἂν θεὸς θέλῃ χἠ τύχη κατορθοῖ,<br>χωρεῖ κατὰ νοῦν, ἕτερον δ᾽ ἑτέρῳ<br>τούτων κατὰ καιρὸν ἀπαντᾷ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὡς ταῦτα δῆλά γ᾽ ἔσθ᾽· ὁ γὰρ βωμὸς θύρασι καὶ δή."}, {"st": null, "sp": "Χορός", "t": "ἐπείγετέ νυν ἐν ὅσῳ<br>σοβαρὰ θεόθεν κατέχει<br>πολέμου μετάτροπος αὔρα.<br>νῦν γὰρ δαίμων φανερῶς<br>εἰς ἀγαθὰ μεταβιβάζει."}, {"st": null, "sp": "Τρυγαῖος", "t": "τὸ κανοῦν πάρεστ᾽ ὀλὰς ἔχον καὶ στέμμα καὶ μάχαιραν,<br>καὶ πῦρ γε τουτί, κοὐδὲν ἴσχει πλὴν τὸ πρόβατον ὑμᾶς."}, {"st": "955", "sp": "Χορός", "t": "οὔκουν ἁμιλλήσεσθον; ὡς<br>ἢν Χαῖρις ὑμᾶς ἴδῃ,<br>πρόσεισιν αὐλήσων ἄκλητος,<br>κᾆτα τοῦτ᾽ εὖ οἶδ᾽ ὅτι<br>φυσῶντι καὶ πονουμένῳ<br>προσδώσετε δήπου."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἄγε δὴ τὸ κανοῦν λαβὼν σὺ καὶ τὴν χέρνιβα<br>περίιθι τὸν βωμὸν ταχέως ἐπιδέξια."}, {"st": null, "sp": "Οἰκέτης", "t": "ἰδού· λεγοις ἂν ἄλλο· περιελήλυθα."}, {"st": null, "sp": "Τρυγαῖος", "t": "φέρε δὴ τὸ δαλίον τόδ᾽ ἐμβάψω λαβών,<br>σείου σὺ ταχέως· σὺ δὲ πρότεινε τῶν ὀλῶν,<br>καὐτός γε χερνίπτου παραδοὺς ταύτην ἐμοί,<br>καὶ τοῖς θεαταῖς ῥῖπτε τῶν κριθῶν."}, {"st": null, "sp": "Οἰκέτης", "t": "ἰδού."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἔδωκας ἤδη;"}, {"st": "965", "sp": "Οἰκέτης", "t": "νὴ τὸν Ἑρμῆν ὥστε γε<br>τούτων ὅσοιπέρ εἰσι τῶν θεωμένων<br>οὐκ ἔστιν οὐδεὶς ὅστις οὐ κριθὴν ἔχει."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐχ αἱ γυναῖκές γ᾽ ἔλαβον."}, {"st": null, "sp": "Οἰκέτης", "t": "ἀλλ᾽ εἰς ἑσπέραν<br>δώσουσιν αὐταῖς ἅνδρες."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ εὐχώμεθα.<br>τίς τῇδε; ποῦ ποτ᾽ εἰσὶ πολλοὶ κἀγαθοί;"}, {"st": null, "sp": "Οἰκέτης", "t": "τοισδὶ φέρε δῶ· πολλοὶ γάρ εἰσι κἀγαθοί."}, {"st": "970", "sp": "Τρυγαῖος", "t": "τούτους ἀγαθοὺς ἐνόμισας;"}, {"st": null, "sp": "Οἰκέτης", "t": "οὐ γάρ, οἵτινες<br>ἡμῶν καταχεόντων ὕδωρ τοσουτονὶ<br>ἐς ταὐτὸ τοῦθ᾽ ἑστᾶσ᾽ ἰόντες χωρίον;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὡς τάχιστ᾽ εὐχώμεθ᾽."}, {"st": null, "sp": "Χορός", "t": "εὐχώμεσθα δή."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ σεμνοτάτη βασίλεια θεὰ<br>πότνι᾽ Εἰρήνη,<br>δέσποινα χορῶν, δέσποινα γάμων,<br>δέξαι θυσίαν τὴν ἡμετέραν."}, {"st": null, "sp": "Χορός", "t": "δέξαι δῆτ᾽ ὦ πολυτιμήτη<br>νὴ Δία, καὶ μὴ ποίει γ᾽ ἅπερ αἱ<br>μοιχευόμεναι δρῶσι γυναῖκες.<br>καὶ γὰρ ἐκεῖναι παρακλίνασαι<br>τῆς αὐλείας παρακύπτουσιν,<br>κἄν τις προσέχῃ τὸν νοῦν αὐταῖς<br>ἀναχωροῦσιν,<br>κᾆτ᾽ ἢν ἀπίῃ παρακύπτουσιν.<br>τούτων σὺ ποίει μηδὲν ἔθ᾽ ἡμᾶς."}, {"st": null, "sp": "Τρυγαῖος", "t": "μὰ Δἴ ἀλλ᾽ ἀπόφηνον ὅλην σαυτὴν<br>γενναιοπρεπῶς τοῖσιν ἐρασταῖς<br>ἡμῖν, οἵ σου τρυχόμεθ᾽ ἤδη<br>τρία καὶ δέκ᾽ ἔτη,<br>λῦσον δὲ μάχας καὶ κορκορυγάς,<br>ἵνα Λυσιμάχην σε καλῶμεν.<br>παῦσον δ᾽ ἡμῶν τὰς ὑπονοίας<br>τὰς περικόμψους,<br>αἷς στωμυλλόμεθ᾽ εἰς ἀλλήλους·<br>μεῖξον δ᾽ ἡμᾶς τοὺς Ἕλληνας<br>πάλιν ἐξ ἀρχῆς<br>φιλίας χυλῷ καὶ συγγνώμῃ<br>τινὶ πρᾳοτέρᾳ κέρασον τὸν νοῦν·<br>καὶ τὴν ἀγορὰν ἡμῖν ἀγαθῶν<br>ἐμπλησθῆναι, μεγάλων σκορόδων,<br>σικύων πρῴων, μήλων, ῥοιῶν.<br>δούλοισι χλανισκιδίων μικρῶν·<br>κἀκ Βοιωτῶν γε φέροντας ἰδεῖν<br>χῆνας νήττας φάττας τροχίλους·<br>καὶ Κωπᾴδων ἐλθεῖν σπυρίδας,<br>καὶ περὶ ταύτας ἡμᾶς ἁθρόους<br>ὀψωνοῦντας τυρβάζεσθαι<br>Μορύχῳ Τελέᾳ Γλαυκέτῃ, ἄλλοις<br>τένθαις πολλοῖς· κᾆτα Μελάνθιον<br>ἥκειν ὕστερον ἐς τὴν ἀγοράν,<br>τὰς δὲ πεπρᾶσθαι, τὸν δ᾽ ὀτοτύζειν,<br>εἶτα μονῳδεῖν ἐκ Μηδείας,<br>“ὀλόμαν ὀλόμαν, ἀποχηρωθεὶς<br>τᾶς ἐν τεύτλοισι λοχευομένας”·<br>τοὺς δ᾽ ἀνθρώπους ἐπιχαίρειν.<br>Τρυγαῖος<br>ταῦτ᾽ ὦ πολυτίμητ᾽ εὐχομένοις ἡμῖν δίδου."}, {"st": null, "sp": "Οἰκέτης", "t": "λαβὲ τὴν μάχαιραν· εἶθ᾽ ὅπως μαγειρικῶς<br>σφάξεις τὸν οἶν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οὐ θέμις."}, {"st": null, "sp": "Οἰκέτης", "t": "τιὴ τί δή;"}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐχ ἥδεται δήπουθεν Εἰρήνη σφαγαῖς,<br>οὐδ᾽ αἱματοῦται βωμός. ἀλλ᾽ εἴσω φέρων<br>θύσας τὰ μηρἴ ἐξελὼν δεῦρ᾽ ἔκφερε,<br>χοὔτω τὸ πρόβατον τῷ χορηγῷ σῴζεται."}, {"st": "1025", "sp": "Χορός", "t": "σέ τοι θύρασι χρὴ . . . μένοντα τοίνυν<br>σχίζας δευρὶ τιθέναι ταχέως<br>τά τε πρόσφορα πάντ᾽ ἐπὶ τούτοις."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὔκουν δοκῶ σοι μαντικῶς τὸ φρύγανον τίθεσθαι;"}, {"st": null, "sp": "Χορός", "t": "πῶς δ᾽ οὐχί; τί γάρ σε πέφευγ᾽<br>ὅσα χρὴ σοφὸν ἄνδρα; τί δ᾽ οὐ<br>σὺ φρονεῖς ὁπόσα χρεών ἐστιν<br>τόν γε σοφῇ δόκιμον<br>φρενὶ πορίμῳ τε τόλμῃ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἡ σχίζα γοῦν ἐνημμένη τὸν Στιλβίδην πιέζει,<br>καὶ τὴν τράπεζαν οἴσομαι, καὶ παιδὸς οὐ δεήσει."}, {"st": null, "sp": "Χορός", "t": "τίς οὖν ἂν οὐκ ἐπαινέσειεν<br>ἄνδρα τοιοῦτον, ὅστις<br>πόλλ᾽ ἀνατλὰς ἔσωσε<br>τὴν ἱερὰν πόλιν;<br>ὥστ᾽ οὐχὶ μὴ παύσῃ ποτ᾽ ὢν<br>ζηλωτὸς ἅπασιν."}, {"st": "1040", "sp": "Οἰκέτης", "t": "ταυτὶ δέδραται. τίθεσο τὼ μηρὼ λαβών.<br>ἐγὼ δ᾽ ἐπὶ σπλάγχν᾽ εἶμι καὶ θυλήματα."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐμοὶ μελήσει ταῦτά γ᾽· ἀλλ᾽ ἥκειν ἐχρῆν."}, {"st": null, "sp": "Οἰκέτης", "t": "ἰδοὺ πάρειμι. μῶν ἐπισχεῖν σοι δοκῶ;"}, {"st": "1045", "sp": "Τρυγαῖος", "t": "ὄπτα καλῶς νυν αὐτά· καὶ γὰρ οὑτοσὶ<br>προσέρχεται δάφνῃ τις ἐστεφανωμένος.<br>τίς ἄρα ποτ᾽ ἐστίν;"}, {"st": null, "sp": "Οἰκέτης", "t": "ὡς ἀλαζὼν φαίνεται·<br>μάντις τίς ἐστιν."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐ μὰ Δἴ ἀλλ᾽ Ἱεροκλέης<br>οὗτός γέ πού ᾽σθ᾽ ὁ χρησμολόγος οὑξ Ὠρεοῦ."}, {"st": null, "sp": "Οἰκέτης", "t": "τί ποτ᾽ ἄρα λέξει;"}, {"st": null, "sp": "Τρυγαῖος", "t": "δῆλός ἐσθ᾽ οὗτός γ᾽ ὅτι<br>ἐναντιώσεταί τι ταῖς διαλλαγαῖς."}, {"st": "1050", "sp": "Οἰκέτης", "t": "οὔκ, ἀλλὰ κατὰ τὴν κνῖσαν εἰσελήλυθεν."}, {"st": null, "sp": "Τρυγαῖος", "t": "μή νυν ὁρᾶν δοκῶμεν αὐτόν."}, {"st": null, "sp": "Οἰκέτης", "t": "εὖ λέγεις."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "τίς ἡ θυσία ποθ᾽ αὑτηὶ καὶ τῷ θεῶν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὀπτα σὺ σιγῇ κἄπαγ᾽ ἀπὸ τῆς ὀσφύος."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ὅτῳ δὲ θύετ᾽ οὐ φράσεθ᾽;"}, {"st": "1055", "sp": "Τρυγαῖος", "t": "ἡ κέρκος ποιεῖ<br>καλῶς;"}, {"st": null, "sp": "Οἰκέτης", "t": "καλῶς δῆτ᾽ ὦ πότνι᾽ Εἰρήνη φίλη."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ἄγε νυν ἀπάρχου κᾆτα δὸς τἀπάργματα."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὀπτᾶν ἄμεινον πρῶτον."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ἀλλὰ ταυταγὶ<br>ἤδη ᾽στὶν ὀπτά."}, {"st": null, "sp": "Τρυγαῖος", "t": "πολλὰ πράττεις, ὅστις εἶ.<br>κατάτεμνε. ποῦ τράπεζα; τὴν σπονδὴν φέρε."}, {"st": "1060", "sp": "Ἱεροκλῆς", "t": "ἡ γλῶττα χωρὶς τέμνεται."}, {"st": null, "sp": "Τρυγαῖος", "t": "μεμνήμεθα.<br>ἀλλ᾽ οἶσθ᾽ ὃ δρᾶσον;"}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ἢν φράσῃς."}, {"st": null, "sp": "Τρυγαῖος", "t": "μὴ διαλέγου<br>νῷν μηδέν· Εἰρήνῃ γὰρ ἱερὰ θύομεν."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ὦ μέλεοι θνητοὶ καὶ νήπιοι,"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐς κεφαλὴν σοί."}, {"st": "1065", "sp": "Ἱεροκλῆς", "t": "οἵτινες ἀφραδίῃσι θεῶν νόον οὐκ ἀίοντες<br>συνθήκας πεποίησθ᾽ ἄνδρες χαροποῖσι πιθήκοις,"}, {"st": null, "sp": "Τρυγαῖος", "t": "αἰβοιβοῖ."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "τί γελᾷς;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἥσθην χαροποῖσι πιθήκοις."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "καὶ κέπφοι τρήρωνες ἀλωπεκιδεῦσι πέπεισθε,<br>ὧν δόλιαι ψυχαί, δόλιαι φρένες."}, {"st": null, "sp": "Τρυγαῖος", "t": "εἴθε σου εἶναι<br>ὤφελεν ὦλαζὼν οὑτωσὶ θερμὸς ὁ πλεύμων."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "εἰ γὰρ μὴ νύμφαι γε θεαὶ Βάκιν ἐξαπάτασκον,<br>μηδὲ Βάκις θνητούς, μηδ᾽ αὖ νύμφαι Βάκιν αὐτὸν —"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐξώλης ἀπόλοι᾽, εἰ μὴ παύσαιο βακίζων."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὔπω θέσφατον ἦν Εἰρήνης δέσμ᾽ ἀναλῦσαι,<br>ἀλλὰ τόδε πρότερον —"}, {"st": null, "sp": "Τρυγαῖος", "t": "τοῖσδ᾽ ἁλσί γε παστέα ταυτί."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὐ γάρ πω τοῦτ᾽ ἐστὶ φίλον μακάρεσσι θεοῖσιν,<br>φυλόπιδος λῆξαι, πρίν κεν λύκος οἶν ὑμεναιοῖ."}, {"st": null, "sp": "Τρυγαῖος", "t": "καὶ πῶς ὦ κατάρατε λύκος ποτ᾽ ἂν οἶν ὑμεναιοῖ;"}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ὡς ἡ σφονδύλη φεύγουσα πονηρότατον βδεῖ,<br>“χἠ κώδων” ἀκαλανθὶς ἐπειγομένη τυφλὰ τίκτει,<br>τουτάκις οὔπω χρῆν τὴν εἰρήνην πεποιῆσθαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλὰ τί χρῆν ἡμᾶς; οὐ παύσασθαι πολεμοῦντας,<br>ἢ διακαυνιάσαι πότεροι κλαυσούμεθα μεῖζον,<br>ἐξὸν σπεισαμένοις κοινῇ τῆς Ἑλλάδος ἄρχειν;"}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὔποτε ποιήσεις τὸν καρκίνον ὀρθὰ βαδίζειν."}, {"st": "1085", "sp": "Τρυγαῖος", "t": "οὔποτε δειπνήσεις ἔτι τοῦ λοιποῦ ν᾽ πρυτανείῳ,<br>οὐδ᾽ ἐπὶ τῷ πραχθέντι ποιήσεις ὕστερον οὐδέν."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὐδέποτ᾽ ἂν θείης λεῖον τὸν τραχὺν ἐχῖνον."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἆρα φενακίζων ποτ᾽ Ἀθηναίους ἔτι παύσει;"}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ποῖον γὰρ κατὰ χρησμὸν ἐκαύσατε μῆρα θεοῖσιν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅνπερ κάλλιστον δήπου πεποίηκεν Ὅμηρος·<br>“ὣς οἱ μὲν νέφος ἐχθρὸν ἀπωσάμενοι πολέμοιο<br>Εἰρήνην εἵλοντο καὶ ἱδρύσανθ᾽ ἱερείῳ.<br>αὐτὰρ ἐπεὶ κατὰ μῆρ᾽ ἐκάη καὶ σπλάγχν᾽ ἐπάσαντο,<br>ἔσπενδον δεπάεσσιν· ἐγὼ δ᾽ ὁδὸν ἡγεμόνευον”·<br>χρησμολόγῳ δ᾽ οὐδεὶς ἐδίδου κώθωνα φαεινόν."}, {"st": "1095", "sp": "Ἱεροκλῆς", "t": "οὐ μετέχω τούτων· οὐ γὰρ ταῦτ᾽ εἶπε Σίβυλλα."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὁ σοφός τοι νὴ Δί᾽ Ὅμηρος δεξιὸν εἶπεν·<br>“ἀφρήτωρ ἀθέμιστος ἀνέστιός ἐστιν ἐκεῖνος,<br>ὃς πολέμου ἔραται ἐπιδημίου ὀκρυόεντος”."}, {"st": "1100", "sp": "Ἱεροκλῆς", "t": "φράζεο δὴ μή πώς σε δόλῳ φρένας ἐξαπατήσας<br>ἰκτῖνος μάρψῃ."}, {"st": null, "sp": "Τρυγαῖος", "t": "τουτὶ μέντοι σὺ φυλάττου,<br>ὡς οὗτος φοβερὸς τοῖς σπλάγχνοις ἐστὶν ὁ χρησμός.<br>ἔγχει δὴ σπονδὴν καὶ τῶν σπλάγχνων φέρε δευρί."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ἀλλ᾽ εἰ ταῦτα δοκεῖ, κἀγὼ ᾽μαυτῷ βαλανεύσω."}, {"st": null, "sp": "Τρυγαῖος", "t": "σπονδὴ σπονδή."}, {"st": "1105", "sp": "Ἱεροκλῆς", "t": "ἔγχει δὴ κἀμοὶ καὶ σπλάγχνων μοῖραν ὄρεξον."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ οὔπω τοῦτ᾽ ἐστὶ φίλον μακάρεσσι θεοῖσιν·<br>ἀλλὰ τόδε πρότερον, σπένδειν ἡμᾶς, σὲ δ᾽ ἀπελθεῖν.<br>ὦ πότνι᾽ Εἰρήνη παράμεινον τὸν βίον ἡμῖν."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "πρόσφερε τὴν γλῶτταν."}, {"st": null, "sp": "Τρυγαῖος", "t": "σὺ δὲ τὴν σαυτοῦ γ᾽ ἀπένεγκε."}, {"st": "1110", "sp": "Ἱεροκλῆς", "t": "σπονδή."}, {"st": null, "sp": "Τρυγαῖος", "t": "καὶ ταυτὶ μετὰ τῆς σπονδῆς λαβὲ θᾶττον."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὐδεὶς προσδώσει τῶν σπλάγχνων;"}, {"st": null, "sp": "Τρυγαῖος", "t": "οὐ γὰρ οἷόν τε<br>ἡμῖν προσδιδόναι, πρίν κεν λύκος οἶν ὑμεναιοῖ."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "ναὶ πρὸς τῶν γονάτων."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἄλλως ὦ τᾶν ἱκετεύεις·<br>οὐ γὰρ ποιήσεις λεῖον τὸν τραχὺν ἐχῖνον.<br>ἄγε δὴ θεαταὶ δεῦρο συσπλαγχνεύετε<br>μετὰ νῷν."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "τί δὴ ᾽γώ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "τὴν Σίβυλλαν ἔσθιε."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "οὔτοι μὰ τὴν γῆν ταῦτα κατέδεσθον μόνω,<br>ἀλλ᾽ ἁρπάσομαι σφῷν αὐτά· κεῖται δ᾽ ἐν μέσῳ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ παῖε τὸν Βάκιν."}, {"st": null, "sp": "Ἱεροκλῆς", "t": "μαρτύρομαι."}, {"st": null, "sp": "Τρυγαῖος", "t": "κἄγωγ᾽ ὅτι τένθης εἶ σὺ κἀλαζὼν ἀνήρ.<br>παἶ αὐτὸν ἐπέχων τῷ ξύλῳ τὸν ἀλαζόνα."}, {"st": null, "sp": "Οἰκέτης", "t": "σὺ μὲν οὖν· ἐγὼ δὲ τουτονὶ τῶν κῳδίων,<br>ἁλάμβαν᾽ αὐτὸς ἐξαπατῶν, ἐκβολβιῶ.<br>οὐ καταβαλεῖς τὰ κῴδι᾽ ὦ θυηπόλε;<br>ἤκουσας; ὁ κόραξ οἷος ἦλθ᾽ ἐξ Ὠρεοῦ.<br>οὐκ ἀποπετήσει θᾶττον εἰς Ἐλύμνιον;"}, {"st": null, "sp": "Χορός", "t": "ἥδομαί γ᾽ ἥδομαι<br>κράνους ἀπηλλαγμένος<br>τυροῦ τε καὶ κρομμύων.<br>οὐ γὰρ φιληδῶ μάχαις,<br>ἀλλὰ πρὸς πῦρ διέλκων<br>μετ᾽ ἀνδρῶν ἑταίρων φίλων,<br>ἐκκέας τῶν ξύλων ἅττ᾽ ἂν ᾖ<br>δανότατα τοῦ θέρους<br>“ἐκπεπρισμένα”,<br>κἀνθρακίζων τοὐρεβίνθου<br>τήν τε φηγὸν ἐμπυρεύων,<br>χἄμα τὴν Θρᾷτταν κυνῶν<br>τῆς γυναικὸς λουμένης."}, {"st": "1155", "sp": "Χορός", "t": "οὐ γὰρ ἔσθ᾽ ἥδιον ἢ τυχεῖν μὲν ἤδη ᾽σπαρμένα,<br>τὸν θεὸν δ᾽ ἐπιψακάζειν, καὶ τιν᾽ εἰπεῖν γείτονα,<br>εἰπέ μοι τί τηνικαῦτα δρῶμεν ὦ Κωμαρχίδη;<br>ἐμπιεῖν ἔμοιγ᾽ ἀρέσκει τοῦ θεοῦ δρῶντος καλῶς.<br>ἀλλ᾽ ἄφευε τῶν φασήλων ὦ γύναι τρεῖς χοίνικας,<br>τῶν τε πυρῶν μεῖξον αὐτοῖς, τῶν τε σύκων ἔξελε,<br>τόν τε Μανῆν ἡ Σύρα βωστρησάτω κ᾽ τοῦ χωρίου.<br>οὐ γὰρ οἷόν τ᾽ ἐστὶ πάντως οἰναρίζειν τήμερον<br>οὐδὲ τυντλάζειν, ἐπειδὴ παρδακὸν τὸ χωρίον.<br>κἀξ ἐμοῦ δ᾽ ἐνεγκάτω τις τὴν κίχλην καὶ τὼ σπίνω·<br>ἦν δὲ καὶ πυός τις ἔνδον καὶ λαγῷα τέτταρα,<br>εἴ τι μὴ ᾽ξήνεγκεν αὐτῶν ἡ γαλῆ τῆς ἑσπέρας·<br>ἐψόφει γοῦν ἔνδον οὐκ οἶδ᾽ ἅττα κἀκυδοιδόπα·<br>ὧν ἔνεγκ᾽ ὦ παῖ τρἴ ἡμῖν, ἓν δὲ δοῦναι τῷ πατρί·<br>μυρρίνας τ᾽ αἴτησον ἐξ Αἰσχινάδου τῶν καρπίμων·<br>χἄμα τῆς αὐτῆς ὁδοῦ Χαρινάδην τις βωσάτω,"}, {"st": null, "sp": "Χορός", "t": "ὡς ἂν ἐμπίῃ μεθ᾽ ἡμῶν,<br>εὖ ποιοῦντος κὠφελοῦντος<br>τοῦ φεοῦ τἀρώματα."}, {"st": null, "sp": "Χορός", "t": "ἡνίκ᾽ ἂν δ᾽ ἀχέτας<br>ᾄδῃ τὸν ἡδὺν νόμον,<br>διασκοπῶν ἥδομαι<br>τὰς Λημυνίας ἀμπέλους,<br>εἰ πεπαίνουσιν ἤ-<br>δη (τὸ γὰρ φῖτυ πρῷον φύσει ),<br>τόν τε φήληχ᾽ ὁρῶν οἰδάνοντ᾽·<br>εἶθ᾽ ὁπόταν ᾖ πέπων,<br>ἐσθίω κἀπέχω<br>χἄμα φήμ᾽, “ὧραι φίλαι”· καὶ<br>τοῦ θύμου τρίβων κυκῶμαι·<br>κᾆτα γίγνομαι παχὺς<br>τηνικαῦτα τοῦ θέρους"}, {"st": null, "sp": "Χορός", "t": "μᾶλλον ἢ θεοῖσιν ἐχθρὸν ταξίαρχον προσβλέπων<br>τρεῖς λόφους ἔχοντα καὶ φοινικίδ᾽ ὀξεῖαν πάνυ,<br>ἣν ἐκεῖνός φησιν εἶναι βάμμα Σαρδιανικόν·<br>ἢν δέ που δέῃ μάχεσθ᾽ ἔχοντα τὴν φοινικίδα,<br>τηνικαῦτ᾽ αὐτὸς βέβαπται βάμμα Κυζικηνικόν·<br>κᾆτα φεύγει πρῶτος ὥσπερ ξουθὸς ἱππαλεκτρυὼν<br>τοὺς λόφους σείων· ἐγὼ δ᾽ ἕστηκα “λινοπτώμενος”.<br>ἡνίκ᾽ ἂν δ᾽ οἴκοι γένωνται, δρῶσιν οὐκ ἀνασχετά,<br>τοὺς μὲν ἐγγράφοντες ἡμῶν τοὺς δ᾽ ἄνω τε καὶ κάτω<br>ἐξαλείφοντες δὶς ἢ τρίς. αὔριον δ᾽ ἔσθ᾽ ἡ ᾽ξοδος·<br>τῷ δὲ σιτί᾽ οὐκ ἐώνητ᾽· οὐ γὰρ ᾔδειν ἐξιών·<br>εἶτα προστὰς πρὸς τὸν ἀνδριάντα τὸν Πανδίονος<br>εἶδεν αὑτόν, κἀπορῶν θεῖ τῷ κακῷ βλέπων ὀπόν.<br>ταῦτα δ᾽ ἡμᾶς τοὺς ἀγροίκους δρῶσι, τοὺς δ᾽ ἐξ ἄστεως<br>ἧττον, οἱ θεοῖσιν οὗτοι κἀνδράσιν ῥιψάσπιδες.<br>ὧν ἔτ᾽ εὐθύνας ἐμοὶ δώσουσιν, ἢν θεὸς θέλῃ."}, {"st": null, "sp": "Χορός", "t": "πολλὰ γὰρ δή μ᾽ ἠδίκησαν,<br>ὄντες οἴκοι μὲν λέοντες<br>ἐν μάχῃ δ᾽ ἀλώπεκες."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἰοὺ ἰού.<br>ὅσον τὸ χρῆμ᾽ ἐπὶ δεῖπνον ἦλθ᾽ ἐς τοὺς γάμους.<br>ἔχ᾽ ἀποκάθαιρε τὰς τραπέζας ταυτῃί·<br>πάντως γὰρ οὐδὲν ὄφελός ἐστ᾽ αὐτῆς ἔτι.<br>ἔπειτ᾽ ἐπιφόρει τοὺς ἀμύλους καὶ τὰς κίχλας<br>καὶ τῶν λαγῴων πολλὰ καὶ τοὺς κολλάβους."}, {"st": null, "sp": "Δρεπανουργός", "t": "ποῦ ποῦ Τρυγαῖός ἐστιν;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀναβράττω κίχλας."}, {"st": null, "sp": "Δρεπανουργός", "t": "ὦ φίλτατ᾽ ὦ Τρυγαῖ᾽ ὅσ᾽ ἡμᾶς τἀγαθὰ<br>δέδρακας εἰρήνην ποιήσας· ὡς πρὸ τοῦ<br>οὐδεὶς ἐπρίατ᾽ ἂν δρέπανον οὐδὲ κολλύβου,<br>νυνὶ δὲ πεντήκοντα δραχμῶν ἐμπολῶ·<br>ὁδὶ δὲ τριδράχμους τοὺς κάδους ἐς τοὺς ἀγρούς.<br>ἀλλ᾽ ὦ Τρυγαῖε τῶν δρεπάνων τε λάμβανε<br>καὶ τῶνδ᾽ ὅ τι βούλει προῖκα· καὶ ταυτὶ δέχου·<br>ἀφ᾽ ὧν γὰρ ἀπεδόμεσθα κἀκερδήναμεν<br>τὰ δῶρα ταυτί σοι φέρομεν ἐς τοὺς γάμους."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἴθι νυν καταθέμενοι παρ᾽ ἐμοὶ ταῦτ᾽ εἴσιτε<br>ἐπὶ δεῖπνον ὡς τάχιστα· καὶ γὰρ οὑτοσὶ<br>ὅπλων κάπηλος ἀχθόμενος προσέρχεται."}, {"st": "1210", "sp": "Λοφοποιός", "t": "οἴμ᾽ ὡς προθέλυμνόν μ᾽ ὦ Τρυγαἶ ἀπώλεσας."}, {"st": null, "sp": "Τρυγαῖος", "t": "τί δ᾽ ἔστιν ὦ κακόδαιμον; οὔτι που λοφᾷς;"}, {"st": null, "sp": "Λοφοποιός", "t": "ἀπώλεσάς μου τὴν τέχνην καὶ τὸν βίον,<br>καὶ τουτουὶ καὶ τοῦ δορυξοῦ ᾽κεινονί."}, {"st": null, "sp": "Τρυγαῖος", "t": "τί δῆτα τουτοινὶ καταθῶ σοι τοῖν λόφοιν;"}, {"st": "1215", "sp": "Λοφοποιός", "t": "αὐτὸς σὺ τί δίδως;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ὅ τι δίδωμ᾽; αἰσχύνομαι.<br>ὅμως δ᾽ ὅτι τὸ σφήκωμ᾽ ἔχει πόνον πολύν,<br>δοίην ἂν αὐτοῖν ἰσχάδων τρεῖς χοίνικας.<br>ἵν᾽ ἀποκαθαίρω τὴν τράπεζαν τουτῳί."}, {"st": "1220", "sp": "Λοφοποιός", "t": "ἔνεγκε τοίνυν εἰσιὼν τὰς ἰσχάδας·<br>κρεῖττον γὰρ ὦ τᾶν ἐστιν ἢ μηδὲν λαβεῖν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀπόφερ᾽ ἀπόφερ᾽ ἐς κόρακας ἀπὸ τῆς οἰκίας.<br>τριχορρυεῖτον, οὐδέν ἐστον τὼ λόφω.<br>οὐκ ἂν πριαίμην οὐδ᾽ ἂν ἰσχάδος μιᾶς."}, {"st": "1225", "sp": "Θωρακοπώλης", "t": "τί δαὶ δεκάμνῳ τῷδε θώρηκος κύτει<br>ἐνημμένῳ κάλλιστα χρήσομαι τάλας;"}, {"st": null, "sp": "Τρυγαῖος", "t": "οὗτος μὲν οὐ μή σοι ποιήσει ζημίαν.<br>ἀλλ᾽ αἶρέ μοι τοῦτόν γε τῆς ἰσωνίας·<br>ἐναποπατεῖν γάρ ἐστ᾽ ἐπιτήδειος πάνυ —"}, {"st": null, "sp": "Θωρακοπώλης", "t": "παῦσαί μ᾽ ὑβρίζων τοῖς ἐμοῖσι χρήμασιν."}, {"st": "1230", "sp": "Τρυγαῖος", "t": "ὡδὶ παραθέντι τρεῖς λίθους. οὐ δεξιῶς;"}, {"st": null, "sp": "Θωρακοπώλης", "t": "ποίᾳ δ᾽ ἀποψήσει ποτ᾽ ὦμαθέστατε;"}, {"st": null, "sp": "Τρυγαῖος", "t": "τῃδὶ διεὶς τὴν χεῖρα διὰ τῆς θαλαμιᾶς<br>καὶ τῇδ᾽."}, {"st": null, "sp": "Θωρακοπώλης", "t": "ἅμ᾽ ἀμφοῖν δῆτ᾽;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἔγωγε νὴ Δία,<br>ἵνα μή γ᾽ ἁλῶ τρύπημα κλέπτων τῆς νεώς."}, {"st": "1235", "sp": "Θωρακοπώλης", "t": "ἔπειτ᾽ ἐπὶ δεκάμνῳ χεσεῖ καθήμενος;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἔγωγε νὴ Δί᾽ ὦπίτριπτ᾽. οἴει γὰρ ἂν<br>τὸν πρωκτὸν ἀποδόσθαι με χιλιῶν δραχμῶν;"}, {"st": null, "sp": "Θωρακοπώλης", "t": "ἴθι δὴ ᾽ξένεγκε τἀργύριον."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὦγαθὲ<br>θλίβει τὸν ὄρρον. ἀπόφερ᾽, οὐκ ὠνήσομαι."}, {"st": null, "sp": "Σαλπιγγοποιός", "t": "τί δ᾽ ἆρα τῇ σάλπιγγι τῇδε χρήσομαι,<br>ἣν ἐπριάμην δραχμῶν ποθ᾽ ἑξήκοντ᾽ ἐγώ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "μόλυβδον ἐς τουτὶ τὸ κοῖλον ἐγχέας<br>ἔπειτ᾽ ἄνωθεν ῥάβδον ἐνθεὶς ὑπόμακρον,<br>γενήσεταί σοι τῶν κατακτῶν κοττάβων."}, {"st": "1245", "sp": "Σαλπιγγοποιός", "t": "οἴμοι καταγελᾷς."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ἕτερον παραινέσω.<br>τὸν μὲν μόλυβδον, ὥσπερ εἶπον, ἔγχεον,<br>ἐντευθενὶ δὲ σπαρτίοις ἠρτημένην<br>πλάστιγγα πρόσθες, καὐτό σοι γενήσεται<br>τὰ σῦκ᾽ ἐν ἀγρῷ τοῖς οἰκέταισιν ἱστάναι."}, {"st": null, "sp": "Κρανοποιός", "t": "ὦ δυσκάθαρτε δαῖμον ὥς μ᾽ ἀπώλεσας,<br>ὅτ᾽ ἀντέδωκά γ᾽ ἀντὶ τῶνδε μνᾶν ποτέ·<br>καὶ νῦν τί δράσω; τίς γὰρ αὔτ᾽ ὠνήσεται;"}, {"st": null, "sp": "Τρυγαῖος", "t": "πώλει βαδίζων αὐτὰ τοῖς Αἰγυπτίοις·<br>ἔστιν γὰρ ἐπιτήδεια συρμαίαν μετρεῖν."}, {"st": "1255", "sp": "Δορυξός", "t": "οἴμ᾽ ὦ κρανοποί᾽ ὡς ἀθλίως πεπράγαμεν."}, {"st": null, "sp": "Τρυγαῖος", "t": "οὗτος μὲν οὐ πέπονθεν οὐδέν."}, {"st": null, "sp": "Δορυξός", "t": "ἀλλὰ τί<br>ἔτ᾽ ἐστὶ τοῖσι κράνεσιν ὅ τι τις χρήσεται;"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἐὰν τοιαυτασὶ μάθῃ λαβὰς ποιεῖν,<br>ἄμεινον ἢ νῦν αὔτ᾽ ἀποδώσεται πολύ."}, {"st": "1260", "sp": "Κρανοποιός", "t": "ἀπίωμεν ὦ δορυξέ."}, {"st": null, "sp": "Τρυγαῖος", "t": "μηδαμῶς γ᾽, ἐπεὶ<br>τούτῳ γ᾽ ἐγὼ τὰ δόρατα ταῦτ᾽ ὠνήσομαι."}, {"st": null, "sp": "Δορυξός", "t": "πόσον δίδως δῆτ᾽;"}, {"st": null, "sp": "Τρυγαῖος", "t": "εἰ διαπρισθεῖεν δίχα,<br>λάβοιμ᾽ ἂν αὔτ᾽ ἐς χάρακας ἑκατὸν τῆς δραχμῆς."}, {"st": null, "sp": "Δορυξός", "t": "ὑβριζόμεθα. χωρῶμεν ὦ τᾶν ἐκποδών."}, {"st": null, "sp": "Τρυγαῖος", "t": "νὴ τὸν Δί᾽, ὡς τὰ παιδί᾽ ἤδη ᾽ξέρχεται<br>οὐρησόμενα τὰ τῶν ἐπικλήτων δεῦρ᾽, ἵνα<br>ἅττ᾽ ᾄσεται προαναβάληταί μοι δοκεῖ.<br>ἀλλ᾽ ὅ τι περ ᾄδειν ἐπινοεῖς ὦ παιδίον,<br>αὐτοῦ παρ᾽ ἐμὲ στὰν πρότερον ἀναβαλοῦ ᾽νθαδί."}, {"st": "1270", "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>νῦν αὖθ᾽ ὁπλοτέρων ἀνδρῶν ἀρχώμεθα —"}, {"st": null, "sp": "Τρυγαῖος", "t": "παῦσαι<br>ὁπλοτέρους ᾆδον, καὶ ταῦτ ὦ τρισκακόδαιμον<br>εἰρήνης οὔσης· ἀμαθές γ᾽ εἶ καὶ κατάρατον."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>οἱ δ᾽ ὅτε δὴ σχεδὸν ἦσαν ἐπ᾽ ἀλλήλοισιν ἰόντες,<br>σύν ῥ᾽ ἔβαλον ῥινούς τε καὶ ἀσπίδας ὀμφαλοέσσας."}, {"st": "1275", "sp": "Τρυγαῖος", "t": "ἀσπίδας; οὐ παύσει μεμνημένος ἀσπίδος ἡμῖν;"}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>ἔνθα δ᾽ ἅμ᾽ οἰμωγή τε καὶ εὐχωλὴ πέλεν ἀνδρῶν."}, {"st": null, "sp": "Τρυγαῖος", "t": "ἀνδρῶν οἰμωγή; κλαύσει νὴ τὸν Διόνυσον<br>οἰμωγὰς ᾄδων, καὶ ταύτας ὀμφαλοέσσας."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>ἀλλὰ τί δῆτ᾽ ᾄδω; σὺ γὰρ εἰπέ μοι οἷστισι χαίρεις."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὣς οἱ μὲν δαίνυντο βοῶν κρέα, καὶ τὰ τοιαυτί·<br>ἄριστον προτίθεντο καὶ ἅτθ᾽ ἥδιστα πάσασθαι."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>ὣς οἱ μὲν δαίνυντο βοῶν κρέα, καὐχένας ἵππων<br>ἔκλυον ἱδρώοντας, ἐπεὶ πολέμου ἐκόρεσθεν."}, {"st": "1285", "sp": "Τρυγαῖος", "t": "εἶεν; ἐκόρεσθεν τοῦ πολέμου κᾆτ᾽ ἤσθιον.<br>ταῦτ᾽ ᾆδε, ταῦθ᾽, ὡς ἤσθιον κεκορημένοι."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>θωρήσσοντ᾽ ἄρ᾽ ὄτειτα πεπαυμένοι —"}, {"st": null, "sp": "Τρυγαῖος", "t": "ἄσμενοι, οἶμαι."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>πύργων δ᾽ ἐξεχέοντο, βοὴ δ᾽ ἄσβεστος ὀρώρει."}, {"st": null, "sp": "Τρυγαῖος", "t": "κάκιστ᾽ ἀπόλοιο παιδάριον αὐταῖς μάχαις·<br>οὐδὲν γὰρ ᾄδεις πλὴν πολέμους. τοῦ καί ποτ᾽ εἶ;"}, {"st": "1290", "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>ἐγώ;"}, {"st": null, "sp": "Τρυγαῖος", "t": "σὺ μέντοι νὴ Δί᾽."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Λαμάχου&gt;<br>υἱὸς Λαμάχου."}, {"st": null, "sp": "Τρυγαῖος", "t": "αἰβοῖ·<br>ἦ γὰρ ἐγὼ θαύμαζον ἀκούων, εἰ σὺ μὴ εἴης<br>ἀνδρὸς βουλομάχου καὶ κλαυσιμάχου τινὸς υἱός.<br>ἄπερρε καὶ τοῖς λογχοφόροισιν ᾆδ᾽ ἰών.<br>ποῦ μοι τὸ τοῦ Κλεωνύμου ᾽στὶ παιδίον;<br>ᾆσον πρὶν εἰσιέναι τι· σὺ γὰρ εὖ οἶδ᾽ ὅτι<br>οὐ πράγματ᾽ ᾄσει· σώφρονος γὰρ εἶ πατρός."}, {"st": null, "sp": "N", "t": "Παῖς &lt;Κλεωνύμου&gt;<br>ἀσπίδι μὲν Σαΐων τις ἀγάλλεται, ἣν παρὰ θάμνῳ<br>ἔντος ἀμώμητον κάλλιπον οὐκ ἐθέλων."}, {"st": "1300", "sp": "Τρυγαῖος", "t": "εἰπέ μοι ὦ πόσθων, ἐς τὸν σαυτοῦ πατέρ᾽ ᾄδεις;"}, {"st": null, "sp": "N", "t": "Παῖς &lt;Κλεωνύμου&gt;<br>ψυχὴν δ᾽ ἐξεσάωσα —"}, {"st": null, "sp": "Τρυγαῖος", "t": "κατῄσχυνας δὲ τοκῆας.<br>ἀλλ᾽ εἰσίωμεν. εὖ γὰρ οἶδ᾽ ἐγὼ σαφῶς<br>ὅτι ταῦθ᾽ ὅσ᾽ ᾖσας ἄρτι περὶ τῆς ἀσπίδος<br>οὐ μὴ ᾽πιλάθῃ ποτ᾽ ὢν ἐκείνου τοῦ πατρός."}, {"st": "1310", "sp": "Τρυγαῖος", "t": "ὑμῶν τὸ λοιπὸν ἔργον ἤδη ᾽νταῦθα τῶν μενόντων<br>φλᾶν ταῦτα πάντα καὶ σποδεῖν, καὶ μὴ κενὰς παρέλκειν.<br>ἀλλ᾽ ἀνδρικῶς ἐμβάλλετε<br>καὶ σμώχετ᾽ ἀμφοῖν τοῖν γνάθοιν· οὐδὲν γὰρ ὦ πόνηροι<br>λευκῶν ὀδόντων ἔργον ἐστ᾽, ἢν μή τι καὶ μασῶνται."}, {"st": null, "sp": "Χορός", "t": "ἡμῖν μελήσει ταῦτά γ᾽· εὖ ποιεῖς δὲ καὶ σὺ φράζων."}, {"st": "1315", "sp": "Τρυγαῖος", "t": "ἀλλ᾽ ὦ πρὸ τοῦ πεινῶντες ἐμβάλλεσθε τῶν λαγῴων·<br>ὡς οὐχὶ πᾶσαν ἡμέραν<br>πλακοῦσιν ἔστιν ἐντυχεῖν πλανωμένοις ἐρήμοις.<br>πρὸς ταῦτα βρύκετ᾽ ἢ τάχ᾽ ἡμῖν φημι μεταμελήσειν."}, {"st": null, "sp": "Χορός", "t": "εὐφημεῖν χρὴ καὶ τὴν νύμφην ἔξω τινὰ δεῦρο κομίζειν<br>δᾷδάς τε φέρειν, καὶ πάντα λεὼν συγχαίρειν κἀπιχορεύειν.<br>καὶ τὰ σκεύη πάλιν ἐς τὸν ἀγρὸν νυνὶ χρὴ πάντα κομίζειν<br>ὀρχησαμένους καὶ σπείσαντας καὶ Ὑπέρβολον ἐξελάσαντας,"}, {"st": null, "sp": "Χορός", "t": "κἀπευξαμένους τοῖσι θεοῖσιν<br>διδόναι πλοῦτον τοῖς Ἕλλησιν,<br>κριθάς τε ποιεῖν ἡμᾶς πολλὰς<br>πάντας ὁμοίως οἶνόν τε πολύν,<br>σῦκά τε τρώγειν,<br>τάς τε γυναῖκας τίκτειν ἡμῖν,<br>καὶ τἀγαθὰ πάνθ᾽ ὅσ᾽ ἀπωλέσαμεν<br>συλλέξασθαι πάλιν ἐξ ἀρχῆς,<br>λῆξαί τ᾽ αἴθωνα σίδηρον."}, {"st": null, "sp": "Τρυγαῖος", "t": "δεῦρ᾽ ὦ γύναι εἰς ἀγρόν,<br>χὤπως μετ᾽ ἐμοῦ καλὴ<br>καλῶς κατακείσει.<br>Ὑμὴν Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "ὦ τρὶς μάκαρ ὡς δικαίως<br>τἀγαθὰ νῦν ἔχεις."}, {"st": "1335", "sp": "Ἡμιχόριον Α", "t": "Ὑμὴν Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "Ὑμὴν Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Ἡμιχόριον Α", "t": "τί δράσομεν αὐτήν;"}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "τί δράσομεν αὐτήν;"}, {"st": null, "sp": "Ἡμιχόριον Α", "t": "τρυγήσομεν αὐτήν,"}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "τρυγήσομεν αὐτήν."}, {"st": null, "sp": "Ἡμιχόριον Α", "t": "ἀλλ᾽ ἀράμενοι φέρωμεν<br>οἱ προτεταγμένοι<br>τὸν νυμφίον ὦνδρες."}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "Ὑμὴν Ὑμέναι᾽ ὦ,"}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "Ὑμὴν Ὑμέναι᾽ ὦ,"}, {"st": null, "sp": "Τρυγαῖος", "t": "οἰκήσετε γοῦν καλῶς<br>οὐ πράγματ᾽ ἔχοντες, ἀλλὰ<br>συκολογοῦντες."}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "Ὑμὴν Ὑμέναι᾽ ὦ,"}, {"st": null, "sp": "Ἡμιχόριον Α", "t": "Ὑμὴν Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Ἡμιχόριον Β", "t": "τοῦ μὲν μέγα καὶ παχύ."}, {"st": "1350", "sp": "Ἡμιχόριον Α", "t": "τῆς δ᾽ ἡδὺ τὸ σῦκον."}, {"st": null, "sp": "Τρυγαῖος", "t": "φήσεις γ᾽ ὅταν ἐσθίῃς<br>οἶνόν τε πίῃς πολύν."}, {"st": null, "sp": "Χορός", "t": "Ὑμὴν Ὑμέναι᾽ ὦ,<br>Ὑμὴν Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Τρυγαῖος", "t": "ὦ χαίρετε χαίρετ᾽ ἄνδρες,<br>κἂν ξυνέπησθέ μοι<br>πλακοῦντας ἔδεσθε."}],[]);})();
